const RAW = [
// ── SIGNALISATION (17) ──────────────────────────────────────────────
{c:"Signalisation",e:"🛑",s:"stop",d:1,m:false,q:"Que signifie ce panneau octogonal rouge ?",o:["Ralentir et donner la priorité","S'arrêter obligatoirement avant de repartir","Interdiction de circuler","Fin de zone prioritaire"],r:[1],x:"Le STOP impose un arrêt COMPLET, même voie libre. Repartir sans s'arrêter = retrait 4 points + amende 135 €.",tip:"🧠 Mémo : STOP = S'arrêTer Obligatoirement, Pas d'exception !"},
{c:"Signalisation",e:"⚠️",s:"cedez",d:1,m:false,q:"Ce panneau triangulaire 'cédez le passage' vous oblige à :",o:["Vous arrêter obligatoirement","Céder le passage aux usagers que vous allez croiser","Rouler à 30 km/h","Klaxonner avant de traverser"],r:[1],x:"Le cédez le passage n'impose pas l'arrêt, mais oblige à laisser passer les prioritaires. Arrêt si la voie n'est pas libre.",tip:"💡 Différence clé : STOP = arrêt obligatoire / Cédez = arrêt si nécessaire"},
{c:"Signalisation",e:"🚫",s:"sens_interdit",d:1,m:false,q:"Ce panneau rond rouge et blanc signifie :",o:["Voie sans issue","Stationnement interdit","Sens interdit : accès impossible depuis votre sens","Interdiction de tourner"],r:[2],x:"Le sens interdit bloque l'accès dans ce sens. Très dangereux de l'emprunter (circulation à contresens).",tip:"⚠️ Contresens = danger immédiat. Faites demi-tour dès que possible."},
{c:"Signalisation",e:"🔶",s:"priorite",d:1,m:false,q:"Ce losange jaune sur fond blanc signifie :",o:["Danger : virage","Vous êtes sur une route prioritaire","Cédez le passage","Zone de travaux"],r:[1],x:"Losange jaune = route prioritaire. Aux intersections, vous avez la priorité sur les routes secondaires.",tip:"🔶 Barré d'un trait noir = FIN de priorité. Attention à la différence !"},
{c:"Signalisation",e:"⚠️",s:"danger",d:2,m:true,q:"Un panneau triangulaire fond blanc liseré rouge peut signaler :",o:["Un virage dangereux","Un passage piéton","Une priorité à droite","Un rétrécissement de chaussée","Un passage à niveau"],r:[0,1,2,3,4],x:"Les panneaux triangulaires signalent TOUS les types de danger : virages, passages piétons, intersections, rétrécissements, passages à niveau…",tip:"🔺 Règle : triangle blanc rouge = DANGER, à anticiper !"},
{c:"Signalisation",e:"🟡",s:"marquage",d:2,m:false,q:"Cette ligne jaune continue au sol vous interdit de :",o:["Vous garer sur le côté","Franchir cette ligne","Dépasser 50 km/h","Tourner à gauche"],r:[1],x:"La ligne jaune continue ne peut pas être franchie. Elle remplace le marquage blanc pendant travaux (même valeur juridique).",tip:"🟡 Jaune = provisoire (travaux). Blanc = permanent. Même contrainte."},
{c:"Signalisation",e:"🔴",s:"feu_r",d:1,m:false,q:"Ce feu rouge fixe signifie :",o:["Vous pouvez passer lentement","Arrêt obligatoire","Ralentissez fortement","Priorité aux piétons seulement"],r:[1],x:"Feu rouge = arrêt absolu. Franchir un feu rouge = retrait 4 points + amende 135 €.",tip:"🚨 Feu grillé + accident = délit. Assurance peut refuser de couvrir."},
{c:"Signalisation",e:"🟠",s:"feu_o",d:1,m:false,q:"Ce feu orange fixe signifie :",o:["Accélérez pour passer avant le rouge","Arrêtez-vous si vous pouvez le faire sans danger","Continuez normalement","Vous êtes prioritaire"],r:[1],x:"Feu orange = rouge imminent. Arrêtez si possible sans danger. Accélérer pour 'griller' l'orange est une infraction.",tip:"⚠️ 'Griller l'orange' est sanctionné comme le rouge si un accident survient."},
{c:"Signalisation",e:"→",s:"feu_fleche",d:2,m:false,q:"Feu rouge + flèche verte clignotante en bas à droite :",o:["Passage libre, vous êtes prioritaire","Tourne-à-droite autorisé en cédant le passage aux piétons et autres","Aucun mouvement possible","Uniquement pour les bus"],r:[1],x:"La flèche verte autorise le mouvement SANS priorité. Vous devez céder le passage aux piétons et aux autres véhicules.",tip:"🟢 Flèche verte = vous pouvez, mais CÉDEZ. Pas prioritaire !"},
{c:"Signalisation",e:"🟢",s:"feu_v",d:1,m:false,q:"Vous arrivez à un feu vert. Vous devez :",o:["Passer sans regarder","Passer en vérifiant que l'intersection est dégagée","Klaxonner pour prévenir les piétons","Accélérer immédiatement"],r:[1],x:"Le feu vert autorise le passage mais ne dispense pas de vigilance. Vérifiez que l'intersection est bien dégagée.",tip:"🟢 Feu vert ≠ priorité absolue. Piétons et véhicules déjà engagés restent prioritaires."},
{c:"Signalisation",e:"⭕",s:"fin_interdiction",d:2,m:false,q:"Ce panneau rond barré de traits gris obliques signifie :",o:["Interdiction de dépasser","Fin d'une interdiction précédemment signalée","Passage interdit","Zone de danger"],r:[1],x:"Panneau 'fin d'interdiction' = levée d'une interdiction précédente (fin de vitesse limitée, fin d'interdiction de doubler…).",tip:"⭕ Fond blanc + traits gris obliques = FIN d'une règle. Reprenez la règle générale."},
{c:"Signalisation",e:"🔵",s:"obligation",d:1,m:false,q:"Un panneau rond bleu avec flèche blanche vers le haut :",o:["Indication : vous pouvez aller tout droit","Obligation d'aller tout droit","Recommandation de vitesse","Voie réservée"],r:[1],x:"Panneaux ronds BLEUS = OBLIGATIONS. Flèche vers le haut = vous devez obligatoirement aller tout droit.",tip:"🔵 Bleu rond = obligation. Bleu carré = indication. Retenez la forme !"},
{c:"Signalisation",e:"🚲",s:"piste_cyclo",d:1,m:false,q:"Ce panneau carré bleu avec un vélo blanc :",o:["Interdit aux cyclistes","Piste cyclable obligatoire pour les cyclistes","Attention cyclistes","Parking vélo"],r:[1],x:"Panneau carré bleu avec vélo = piste ou voie cyclable obligatoire pour les cyclistes. Les autres véhicules y sont interdits.",tip:"🚲 Les cyclistes DOIVENT emprunter cette piste si disponible."},
{c:"Signalisation",e:"🏁",s:"zone30",d:2,m:true,q:"Entrer dans une Zone 30 implique obligatoirement :",o:["Vitesse limitée à 30 km/h","Les piétons peuvent traverser partout","Priorité à droite rétablie","Les cyclistes peuvent circuler dans les 2 sens","Stationnement interdit"],r:[0,1,2,3],x:"Zone 30 : 30 km/h, piétons traversent partout, priorité à droite, cyclistes souvent à contresens. Stationnement non automatiquement interdit.",tip:"📍 Zone 30 ≠ zone de rencontre (20 km/h). Ne confondez pas !"},
{c:"Signalisation",e:"🔴",s:"interdit",d:1,m:false,q:"Un panneau rond blanc liseré rouge signifie :",o:["Une obligation","Une interdiction","Un danger","Une indication"],r:[1],x:"Panneaux ronds fond blanc liseré rouge = INTERDICTION (vitesse, dépassement, sens interdit, tourner…).",tip:"🔴 Blanc + rouge + rond = INTERDIT. C'est la forme de base à mémoriser."},
{c:"Signalisation",e:"🚌",d:2,m:false,q:"Un panneau rectangulaire bleu avec un bus blanc indique :",o:["Un arrêt de bus facultatif","Une voie réservée aux bus et taxis","Une zone de ramassage scolaire","Un parking relais"],r:[1],x:"Voie réservée aux transports en commun (bus, taxis). Les autres véhicules ne peuvent pas y circuler, sauf pour tourner ou stationner.",tip:"🚌 Voie bus = amende + retrait de points si franchie sans raison."},
{c:"Signalisation",e:"🟡",d:2,m:false,q:"Un feu de signalisation clignotant orange signifie :",o:["Arrêt obligatoire","Carrefour à sens giratoire","Prudence, ralentissez et cédez le passage","Accélérez, la voie est libre"],r:[2],x:"Feu orange clignotant = intersection non régulée. Appliquez les règles normales de priorité avec vigilance accrue.",tip:"🟡 Clignotant = régime normal de priorité. Soyez attentif."},

// ── PRIORITÉS (11) ──────────────────────────────────────────────────
{c:"Priorités",e:"🔄",d:1,m:false,q:"Dans un giratoire signalisé 'cédez le passage', qui est prioritaire ?",o:["Le véhicule qui entre","Le véhicule déjà dans le giratoire","Le véhicule le plus à droite","Le premier arrivé"],r:[1],x:"Dans un rond-point signalisé, les véhicules dans le giratoire sont prioritaires sur ceux qui entrent.",tip:"🔄 Retournez la règle : c'est l'inverse de la priorité à droite classique !"},
{c:"Priorités",e:"🚶",d:1,m:false,q:"Un piéton s'apprête à traverser sur un passage piéton :",o:["Klaxonnez pour le prévenir","Arrêtez-vous et cédez-lui le passage","Ralentissez seulement si nécessaire","Accélérez pour passer avant lui"],r:[1],x:"Piéton qui s'apprête à traverser = PRIORITAIRE. Arrêt obligatoire. Infraction = retrait 6 points.",tip:"🚶 'S'apprête à traverser' suffit. Pas besoin qu'il soit déjà sur le passage."},
{c:"Priorités",e:"🏔️",d:2,m:false,q:"Route étroite en montagne, le véhicule qui descend face à vous :",o:["Il est prioritaire, vous cédez","Le véhicule qui monte est prioritaire, il est difficile de reculer","La priorité à droite s'applique","Le plus petit véhicule cède"],r:[0],x:"Le véhicule qui MONTE est prioritaire. Celui qui descend s'efface ou recule pour laisser passer. Reculer en descente est plus facile.",tip:"⛰️ Mnémotechnique : en montée, moteur chargé, reculer = dangereux. Le descendant cède."},
{c:"Priorités",e:"🚑",d:2,m:true,q:"Un véhicule prioritaire (sirène + gyrophare) arrive derrière vous :",o:["Continuer normalement","Serrer à droite et ralentir ou s'arrêter","Accélérer pour dégager","Allumer les feux de détresse","Sur autoroute : libérer la BAU"],r:[1,3,4],x:"Face à un véhicule prioritaire : serrez à droite, ralentissez/arrêtez, allumez les warnings. Sur autoroute, libérez la BAU. Ne jamais accélérer.",tip:"🚑 Prioritaires : pompiers, SAMU, police, gendarmerie, douanes en mission."},
{c:"Priorités",e:"🚲",d:2,m:false,q:"Vous sortez d'un parking, un cycliste arrive sur la piste cyclable :",o:["Vous êtes prioritaire","Le cycliste est prioritaire","Priorité à droite classique","Celui qui arrive le premier"],r:[1],x:"Le cycliste sur une piste cyclable est prioritaire sur un véhicule sortant d'un parking ou d'une propriété.",tip:"🚲 Règle générale : le sortant d'une propriété privée cède TOUJOURS le passage."},
{c:"Priorités",e:"↩️",d:2,m:false,q:"Vous tournez à gauche, un cycliste arrive en sens inverse tout droit :",o:["Vous êtes prioritaire car vous avez le clignotant","Le cycliste est prioritaire","Vous si vous êtes déjà engagé","Égalité de priorité"],r:[1],x:"Toute manœuvre doit s'effectuer sans gêner les autres. Le cycliste allant tout droit est prioritaire sur votre tourne-à-gauche.",tip:"↩️ Clignotant = signal, pas passe-droit. Vous devez attendre."},
{c:"Priorités",e:"🚗",d:1,m:false,q:"Intersection non signalisée : la priorité appartient à :",o:["Au plus rapide","Au plus gros véhicule","Au véhicule arrivant par la droite","Au premier arrivé"],r:[2],x:"Règle de la priorité à droite : à toute intersection non signalisée, cédez le passage au véhicule arrivant de votre droite.",tip:"➡️ Priorité à droite = règle de base. Elle cède uniquement face à une signalisation spécifique."},
{c:"Priorités",e:"🚌",d:1,m:false,q:"Un autobus signale qu'il quitte son arrêt (clignotant) :",o:["Accélérez pour passer avant lui","Cédez-lui le passage si possible sans danger","Arrêtez-vous obligatoirement","Ignorez-le si vous êtes sur la voie principale"],r:[1],x:"Un bus qui redémarre a une priorité de fait. Cédez-lui le passage si cela peut se faire sans danger.",tip:"🚌 Le bus cède si 'sans danger' est impossible. Pas toujours prioritaire absolument."},
{c:"Priorités",e:"🚜",d:2,m:false,q:"Sur route étroite, vous croisez un tracteur agricole trop large :",o:["Klaxonnez pour qu'il s'arrête","Vous vous effacez car vous êtes le plus maniable","Continuez : c'est à lui de trouver une solution","Priorité à droite classique"],r:[1],x:"Sur route étroite, le véhicule le plus facile à manœuvrer cède généralement le passage.",tip:"🚜 Bon sens pratique : celui qui peut s'effacer le plus facilement le fait."},
{c:"Priorités",e:"🚋",d:3,m:false,q:"Un tramway sur la voie publique est :",o:["Prioritaire grâce à sa masse","Soumis à la priorité à droite","Prioritaire car il ne peut pas dévier de ses rails","Le piéton est prioritaire sur le tram"],r:[2],x:"Le tramway, guidé sur ses rails, ne peut ni freiner brusquement ni dévier. Il est toujours prioritaire.",tip:"🚋 Rails = impossible de dévier. Jamais de conflit à son encontre !"},
{c:"Priorités",e:"↕️",d:2,m:false,q:"Vous descendez une côte étroite, un véhicule monte en face :",o:["Vous passez car vous descendez","Vous cédez le passage, il monte","Priorité à droite, même en côte","Le plus gros passe"],r:[1],x:"Le véhicule qui monte est prioritaire. En descendant, reculer ou s'effacer est plus facile.",tip:"⛰️ Montée = effort + risque de caler. Le montant est prioritaire."},

// ── VITESSE (10) ────────────────────────────────────────────────────
{c:"Vitesse",e:"💨",s:"v130",d:1,m:false,q:"Vitesse maximale sur autoroute par temps sec (conducteur expérimenté) ?",o:["110 km/h","120 km/h","130 km/h","150 km/h"],r:[2],x:"130 km/h sur autoroute par temps sec. Réduite à 110 km/h par pluie ou en période probatoire, 50 km/h si visibilité < 50 m.",tip:"🏎️ 130 → 110 (pluie) → 50 (brouillard dense) → mémoriser cette cascade."},
{c:"Vitesse",e:"🏙️",s:"v50",d:1,m:false,q:"Vitesse maximale par défaut en agglomération ?",o:["30 km/h","50 km/h","70 km/h","45 km/h"],r:[1],x:"50 km/h en agglomération par défaut, sauf signalisation contraire (Zone 30 : 30 km/h, zone de rencontre : 20 km/h).",tip:"🏙️ Repère : en ville → 50 km/h. Zone 30 → 30. Zone rencontre → 20 (piétons = rois)."},
{c:"Vitesse",e:"🛣️",s:"v80",d:1,m:false,q:"Sur route bidirectionnelle sans séparateur central, hors agglomération ?",o:["90 km/h","100 km/h","80 km/h","70 km/h"],r:[2],x:"Depuis juillet 2018 : 80 km/h sur routes bidirectionnelles sans séparateur central (anciennement 90 km/h).",tip:"📅 Réforme 2018 : 90 → 80. Sujet qui revient souvent à l'examen !"},
{c:"Vitesse",e:"🌫️",d:1,m:false,q:"Visibilité inférieure à 50 m (brouillard dense) : vitesse maximale ?",o:["70 km/h","50 km/h","30 km/h","Pas de limite spécifique"],r:[1],x:"Visibilité < 50 m = 50 km/h sur TOUTES les routes, y compris l'autoroute.",tip:"🌫️ 50 m de visibilité = 50 km/h. Facile à mémoriser, les deux chiffres se correspondent !"},
{c:"Vitesse",e:"🆕",s:"v110",d:2,m:true,q:"Un conducteur en période probatoire (permis récent) :",o:["130 km/h sur autoroute","110 km/h sur autoroute","80 km/h sur route (inchangé)","100 km/h sur voies express","Taux alcool réduit à 0,2 g/L"],r:[1,2,3,4],x:"Période probatoire : 110 km/h autoroute, 100 km/h voies express, 80 km/h routes. Taux alcool 0,2 g/L. Durée : 3 ans (2 ans avec AAC).",tip:"🆕 AAC = Apprentissage Anticipé = permis plus vite (2 ans au lieu de 3 ans de probatoire)."},
{c:"Vitesse",e:"🏘️",s:"zone30",d:1,m:false,q:"Dans une zone de rencontre, la vitesse maximale est :",o:["30 km/h","20 km/h","10 km/h","5 km/h"],r:[1],x:"Zone de rencontre = 20 km/h. Piétons et cyclistes prioritaires, peuvent circuler partout.",tip:"🐢 Zone rencontre : piétons rois, cyclistes rois, 20 km/h. La voiture est invitée."},
{c:"Vitesse",e:"📏",d:2,m:false,q:"Distance de sécurité minimale recommandée à 130 km/h sur autoroute :",o:["50 mètres","100 mètres","130 mètres","200 mètres"],r:[2],x:"Distance de sécurité ≈ vitesse en km/h exprimée en mètres. À 130 km/h = 130 m minimum recommandé (règle des 2 secondes).",tip:"⚡ Astuce : vitesse (km/h) ≈ distance (m). 80 km/h = 80 m. Simple !"},
{c:"Vitesse",e:"🌧️",s:"v110",d:2,m:true,q:"Par temps de pluie, quelles limitations sont réduites ?",o:["Autoroute : 110 km/h","Voies express : 100 km/h","Routes bidirectionnelles : 80 km/h (inchangé)","Agglomération : 30 km/h"],r:[0,1,2],x:"Pluie : autoroute 110, voies express 100, routes 80 (inchangé). Agglomération reste à 50 km/h.",tip:"🌧️ Route 80 = inchangée par pluie. C'est le piège classique !"},
{c:"Vitesse",e:"⚡",d:2,m:false,q:"Un dépassement de vitesse supérieur à 50 km/h entraîne :",o:["Simple amende forfaitaire","Retrait de 2 points","Retrait de 6 points + suspension ou annulation possible","Retrait de 4 points seulement"],r:[2],x:"Dépassement > 50 km/h : délit pénal, retrait 6 points, suspension ou annulation du permis, immobilisation du véhicule possible.",tip:"💥 > 50 km/h = délit (pas contravention). Traité au tribunal correctionnel."},
{c:"Vitesse",e:"🛤️",d:2,m:false,q:"Sur route à 2×2 voies avec séparateur central, hors autoroute :",o:["130 km/h","110 km/h","90 km/h","80 km/h"],r:[1],x:"Voies express à 2×2 voies avec séparateur central (hors autoroute) = 110 km/h (réduit à 100 km/h par pluie).",tip:"🛣️ 2x2 voies ≠ autoroute. Pas de péage = voie express (110) pas autoroute (130)."},

// ── ALCOOL (8) ──────────────────────────────────────────────────────
{c:"Alcool",e:"🍺",d:1,m:false,q:"Taux d'alcoolémie maximum autorisé pour un conducteur expérimenté ?",o:["0,8 g/L","0,5 g/L (soit 0,25 mg/L d'air expiré)","0,3 g/L","0,2 g/L"],r:[1],x:"Taux légal : 0,5 g/L dans le sang ou 0,25 mg/L d'air expiré. Au-delà de 0,8 g/L : délit pénal.",tip:"🍺 0,5 g/L ≈ 2 verres pour 70 kg. Mais le métabolisme varie énormément : ne prenez pas de risque !"},
{c:"Alcool",e:"🎓",d:1,m:false,q:"Taux d'alcoolémie autorisé pour un conducteur en période probatoire ?",o:["0,5 g/L","0,2 g/L","Zéro absolu","0,3 g/L"],r:[1],x:"Période probatoire : 0,2 g/L dans le sang (0,10 mg/L d'air expiré). Quasi-zéro tolérance.",tip:"🎓 0,2 g/L = quasi-abstinence obligatoire. Un seul verre peut dépasser ce seuil."},
{c:"Alcool",e:"⚖️",d:2,m:true,q:"Conduire avec un taux entre 0,5 et 0,8 g/L entraîne :",o:["Amende de 135 €","Retrait de 6 points","Suspension du permis possible","Emprisonnement automatique","Immobilisation du véhicule possible"],r:[0,1,2],x:"Entre 0,5 et 0,8 g/L : contravention (135 €), retrait 6 points, suspension possible. Emprisonnement non automatique à ce niveau.",tip:"⚖️ 0,5-0,8 g/L = contravention (pas délit). Au-delà de 0,8 = délit pénal."},
{c:"Alcool",e:"💊",d:2,m:false,q:"Conduire après consommation de stupéfiants (cannabis, cocaïne…) est :",o:["Toléré si la conduite reste correcte","Un délit, même sans alcool et sans seuil minimum","Interdit seulement en agglomération","Uniquement interdit pour les novices"],r:[1],x:"Conduite sous stupéfiants = délit systématique, sans seuil. Peines : 2 ans emprisonnement + 4 500 € d'amende + 6 points retirés.",tip:"🚫 Pas de 'seuil légal' pour les drogues : toute trace détectée = délit automatique."},
{c:"Alcool",e:"💊",d:2,m:false,q:"Comment identifier un médicament pouvant affecter la conduite ?",o:["Demander au garagiste","Pictogramme sur la boîte (niveaux 1, 2 ou 3)","Tester dans un parking vide","Les médicaments n'affectent jamais la conduite"],r:[1],x:"Niveaux : 1 (prudence), 2 (très prudent, avis médical), 3 (danger, ne pas conduire). Lisez toujours la notice.",tip:"💊 Niveau 3 = voiture barrée rouge. Ne conduisez pas. Consultez votre médecin."},
{c:"Alcool",e:"🍷",d:2,m:true,q:"Substances altérant la conduite et détectables lors d'un contrôle :",o:["L'alcool","Le cannabis (THC)","La cocaïne","Les amphétamines","Les médicaments de niveau 3"],r:[0,1,2,3,4],x:"Alcool, cannabis, cocaïne, amphétamines et médicaments de niveau 3 altèrent tous gravement la conduite et sont détectables.",tip:"🔬 Le cannabis reste détectable jusqu'à 30 jours après consommation dans le sang."},
{c:"Alcool",e:"🚗",d:3,m:false,q:"Alcoolémie > 0,8 g/L avec accident corporel grave : peines maximales :",o:["1 an d'emprisonnement et 4 500 €","Jusqu'à 7 ans d'emprisonnement et 100 000 €","Uniquement une amende majorée","10 ans de suspension automatique"],r:[1],x:"Alcool > 0,8 g/L + accident grave : jusqu'à 7 ans d'emprisonnement et 100 000 € d'amende. Peines alourdies si cumul avec vitesse ou fuite.",tip:"😱 7 ans d'emprisonnement = même peine que certains crimes. Conduire bourré tue."},
{c:"Alcool",e:"🧪",d:2,m:false,q:"Depuis 2012, tout conducteur doit avoir dans son véhicule :",o:["Un éthylotest chimique homologué","Un alcootest électronique professionnel","Une ordonnance médicale","Ce n'est obligatoire que pour les poids lourds"],r:[0],x:"Un éthylotest homologué (chimique ou électronique) est obligatoire dans chaque véhicule. Amende en cas d'absence : 11 €.",tip:"🧪 L'éthylotest sert à se tester SOI-MÊME avant de prendre le volant. Utilité préventive !"},

// ── STATIONNEMENT (6) ───────────────────────────────────────────────
{c:"Stationnement",e:"🅿️",d:2,m:false,q:"Distance minimale en amont d'un passage piéton pour stationner ?",o:["3 m","5 m","10 m","15 m"],r:[1],x:"Interdit de stationner à moins de 5 m en amont d'un passage piéton (masque la visibilité des piétons).",tip:"🅿️ 5 m en AMONT (avant). En aval (après) : pas de distance fixe mais bon sens."},
{c:"Stationnement",e:"🚒",d:1,m:false,q:"Stationner devant l'entrée carrossable d'un garage privé est :",o:["Toléré 30 minutes","Autorisé si vous restez dans le véhicule","Interdit en toutes circonstances","Autorisé la nuit uniquement"],r:[2],x:"Interdit de stationner devant toute entrée carrossable, même brièvement. Cela bloque l'accès.",tip:"🚗 Même 2 minutes = infraction. Le propriétaire peut appeler la fourrière immédiatement."},
{c:"Stationnement",e:"🚌",d:2,m:false,q:"Distance minimale d'un arrêt de bus pour l'interdiction d'arrêt ?",o:["5 m","10 m","15 m","20 m"],r:[2],x:"Arrêt et stationnement interdits à moins de 15 m de part et d'autre d'un arrêt de bus signalisé.",tip:"🚌 15 m = environ 2 longueurs de voiture. Une règle à ne pas minimiser."},
{c:"Stationnement",e:"⛽",d:2,m:false,q:"Stationnement interdit à quelle distance d'une bouche d'incendie ?",o:["3 m","5 m","10 m","Pas de règle spécifique"],r:[1],x:"Bouche d'incendie doit rester accessible aux pompiers. Stationnement interdit à moins de 5 m.",tip:"🔥 En cas d'incendie, les pompiers peuvent briser votre vitre et passer le tuyau. Sans blague !"},
{c:"Stationnement",e:"🔴",d:2,m:true,q:"Où est-il TOUJOURS interdit de stationner ?",o:["Sur un passage piéton","À moins de 5 m d'une intersection","Devant un panneau STOP","Sur une voie de tram","En double file"],r:[0,1,2,3,4],x:"Toutes ces situations sont des infractions : passage piéton, < 5 m intersection, devant Stop, voies de tram, double file.",tip:"📋 Mémo : piétons, intersections, stops, trams, double file = toujours interdit."},
{c:"Stationnement",e:"🚔",d:1,m:false,q:"Le 'stationnement gênant' (ex. sur trottoir) est sanctionné par :",o:["Une simple mise en garde","Mise en fourrière possible + amende","Une amende uniquement","Aucune sanction si < 1h"],r:[1],x:"Stationnement gênant = amende + mise en fourrière immédiate possible. Le trottoir est réservé aux piétons.",tip:"🛞 Fourrière = frais importants (150 à 300 €). Le stationnement gênant ne paie pas !"},

// ── SÉCURITÉ (12) ───────────────────────────────────────────────────
{c:"Sécurité",e:"🔒",d:1,m:false,q:"La ceinture de sécurité est obligatoire :",o:["Seulement sur autoroute","Seulement pour le conducteur","Pour tous les occupants, sur tous les sièges, sur toutes les routes","Seulement pour les passagers avant"],r:[2],x:"La ceinture est obligatoire pour tous les occupants (avant et arrière) sur tous les types de voies. Infraction = retrait 3 points.",tip:"🔒 En cas d'accident sans ceinture, l'assurance peut réduire l'indemnisation."},
{c:"Sécurité",e:"👶",d:2,m:false,q:"Un enfant de moins de 10 ans et moins de 135 cm doit être installé :",o:["Sur le siège avant avec l'airbag activé","Sur le siège arrière avec un siège adapté à son gabarit","Sur le siège avant sans airbag","N'importe où avec une ceinture adulte"],r:[1],x:"Enfant < 10 ans ou < 135 cm : siège homologué adapté au poids, à l'arrière si airbag passager activé.",tip:"👶 Siège dos à la route + airbag = DANGEREUX. Désactivez l'airbag ou mettez à l'arrière."},
{c:"Sécurité",e:"📱",d:1,m:false,q:"Téléphoner au volant en tenant le téléphone en main est :",o:["Autorisé aux feux rouges","Autorisé si l'appel dure moins de 30 secondes","Interdit en toutes circonstances pendant la conduite","Toléré hors agglomération"],r:[2],x:"Téléphone tenu en main = interdit. Amende 135 € + retrait 3 points. Même le kit mains-libres multiplie le risque.",tip:"📱 Même à l'arrêt moteur tournant = infraction. Garez-vous pour téléphoner."},
{c:"Sécurité",e:"🦺",d:2,m:true,q:"En cas de panne ou d'accident sur route, vous devez :",o:["Rester dans le véhicule et attendre","Enfiler le gilet fluorescent AVANT de sortir","Poser le triangle à au moins 30 m en amont","Appeler les secours (15, 17 ou 18 ou 112)","Mettre les feux de détresse immédiatement"],r:[1,2,3,4],x:"Protocole : feux de détresse → gilet AVANT de sortir → triangle ≥ 30 m (150-200 m sur autoroute) → appel secours.",tip:"🔢 Ordre : 1.Warnings 2.Gilet 3.Triangle 4.Appel. Jamais sortir sans gilet !"},
{c:"Sécurité",e:"😴",d:2,m:false,q:"À 130 km/h, une seconde d'inattention correspond à :",o:["18 mètres parcourus à l'aveugle","36 mètres parcourus à l'aveugle","50 mètres parcourus à l'aveugle","72 mètres parcourus à l'aveugle"],r:[1],x:"À 130 km/h = 36 m/s. 1 seconde d'inattention = 36 m à l'aveugle. La fatigue multiplie le risque d'accident par 3.",tip:"😴 Règle d'or : s'arrêter toutes les 2 h max, 15-20 min de pause minimum."},
{c:"Sécurité",e:"💧",d:2,m:false,q:"Sur route mouillée, la distance de freinage est :",o:["Identique au sec","Augmentée d'environ 30 %","Doublée voire plus","Réduite grâce à l'ABS"],r:[2],x:"Distance de freinage sur sol mouillé : ×1,5 à ×2 selon la vitesse et l'état des pneus. L'ABS réduit la distance mais ne l'élimine pas.",tip:"💧 Pneus usés + pluie = risque aquaplaning. Vérifiez la profondeur des rainures (min 1,6 mm)."},
{c:"Sécurité",e:"💺",d:3,m:false,q:"Un siège bébé dos à la route avec airbag passager activé :",o:["C'est la position la plus sûre","C'est dangereux : l'airbag peut tuer le bébé","C'est toléré si le siège est homologué","L'airbag ne pose aucun problème pour un siège homologué"],r:[1],x:"Siège dos à la route + airbag passager activé = DANGER DE MORT. L'airbag frappe le siège vers l'enfant. Désactivez-le impérativement.",tip:"☠️ L'airbag se déploie à 300 km/h. Un enfant dos à la route = impact fatal."},
{c:"Sécurité",e:"🏍️",d:1,m:false,q:"Le port du casque homologué est obligatoire pour :",o:["Les cyclomoteurs seulement","Les motos seulement","Tous les conducteurs et passagers de 2-roues motorisés","Les cyclistes professionnels"],r:[2],x:"Casque homologué obligatoire pour conducteur ET passager de tout 2-roues motorisé. Amende 135 € + retrait 3 points.",tip:"⛑️ Casque à la main mais pas sur la tête = infraction. Portez-le !"},
{c:"Sécurité",e:"⏱️",d:2,m:false,q:"Le temps de réaction moyen d'un conducteur attentif est d'environ :",o:["0,5 seconde","1 seconde","2 secondes","3 secondes"],r:[1],x:"Temps de réaction moyen : 1 seconde. À 50 km/h = 14 m parcourus avant de freiner. Alcool et fatigue peuvent le tripler.",tip:"⏱️ Temps de réaction + freinage = distance d'arrêt totale. Gardez vos distances !"},
{c:"Sécurité",e:"🌊",d:2,m:false,q:"En cas d'aquaplaning (perte d'adhérence sur film d'eau), vous devez :",o:["Freiner brusquement","Accélérer pour sortir du phénomène","Relâcher l'accélérateur progressivement et tenir le volant droit","Tourner le volant brusquement"],r:[2],x:"Aquaplaning : ne pas freiner brusquement ni accélérer. Relâcher doucement l'accélérateur, tenir le cap jusqu'au retour d'adhérence.",tip:"🌊 L'aquaplaning survient dès 70 km/h sur eau. Ralentissez et réduisez la pression des pneus."},
{c:"Sécurité",e:"🔧",d:2,m:true,q:"Documents et équipements obligatoires dans tout véhicule :",o:["Permis de conduire","Carte grise (certificat d'immatriculation)","Attestation d'assurance","Gilet fluorescent","Triangle de pré-signalisation"],r:[0,1,2,3,4],x:"Tous ces éléments sont obligatoires. L'absence du permis, de la carte grise ou de l'assurance est une infraction immédiatement sanctionnable.",tip:"📋 Mémo 5P : Permis, Papiers, Police d'assurance, Protection (gilet), Prévention (triangle)."},
{c:"Sécurité",e:"🌡️",d:2,m:false,q:"Par forte chaleur, vous devez particulièrement surveiller :",o:["Uniquement le niveau d'huile","La pression des pneus (elle augmente avec la chaleur)","Uniquement le liquide de refroidissement","Rien de spécifique, la chaleur n'affecte pas le véhicule"],r:[1],x:"Chaleur = pression des pneus augmente (~0,1 bar/10°C). Vérifiez à froid. Sur-gonflés = surface de contact réduite et risque d'éclatement.",tip:"🌡️ Vérifiez TOUJOURS la pression à froid (avant de rouler ou après 2h d'arrêt)."},

// ── CONDUITE (12) ───────────────────────────────────────────────────
{c:"Conduite",e:"🚗",d:2,m:false,q:"Le dépassement par la droite est :",o:["Toujours autorisé","Interdit sauf si le véhicule de gauche tourne à gauche","Toujours interdit","Autorisé uniquement sur autoroute"],r:[1],x:"Le dépassement par la droite est interdit sauf exception : véhicule de gauche tournant à gauche, embouteillage multi-files, voie réservée.",tip:"➡️ Exception : embouteillage = toutes les files avancent lentement, on peut dépasser à droite."},
{c:"Conduite",e:"➖",d:1,m:false,q:"Dépasser en franchissant une ligne blanche continue est :",o:["Autorisé si visibilité suffisante","Autorisé pour doubler un cycliste","Strictement interdit","Toléré si le dépassement est rapide"],r:[2],x:"Ligne blanche continue = interdiction absolue de franchir ou de dépasser. Amende 135 € + retrait 1 point.",tip:"➖ Continue = interdit de franchir. Discontinue = autorisé avec précaution."},
{c:"Conduite",e:"🔄",d:1,m:false,q:"Avant tout changement de voie, vous devez :",o:["Klaxonner","Vérifier les angles morts et actionner le clignotant avant la manœuvre","Vous arrêter pour vérifier","Actionner les feux de détresse"],r:[1],x:"Clignotant AVANT la manœuvre (pas pendant). Vérifier rétroviseur ET angle mort. Céder le passage aux véhicules présents.",tip:"👁️ Angle mort = zone non visible dans le rétroviseur. Tournez la tête pour vérifier !"},
{c:"Conduite",e:"🔁",d:2,m:false,q:"Le demi-tour est interdit :",o:["Partout en agglomération","Sur autoroute, voie express, et en haut d'une côte ou virage","Uniquement la nuit","Dès qu'un autre véhicule est visible"],r:[1],x:"Demi-tour interdit : autoroute, voie express, sommet de côte, virage, mauvaise visibilité. En ville, un seul mouvement sans gêner.",tip:"↩️ Vous avez raté votre sortie sur l'autoroute ? Allez à la prochaine, pas de demi-tour !"},
{c:"Conduite",e:"🔙",d:2,m:false,q:"Effectuer une marche arrière sur l'autoroute est :",o:["Autorisé sur la BAU si vous avez raté une sortie","Un délit grave (retrait 4 points + amende 135 €)","Toléré si la distance est courte","Autorisé avec les feux de détresse allumés"],r:[1],x:"Marche arrière sur autoroute = DÉLIT. Retrait 4 points + amende 135 €. En cas d'erreur, continuez jusqu'à la prochaine sortie.",tip:"🚨 Marche arrière sur autoroute = danger de mort. Risque de collision mortelle à 130 km/h."},
{c:"Conduite",e:"🚛",d:2,m:false,q:"L'angle mort ('couloir invisible') des camions se situe :",o:["Uniquement derrière le camion","Devant, derrière et sur les côtés (jusqu'à 3 m)","Uniquement à gauche du camion","N'existe pas avec les rétroviseurs modernes"],r:[1],x:"Les camions ont d'importants angles morts devant (5 m), sur les côtés et derrière. Ne restez jamais dans ces zones.",tip:"🚛 Si vous ne voyez pas le rétroviseur du camion, le chauffeur ne vous voit pas non plus !"},
{c:"Conduite",e:"🌙",d:1,m:false,q:"La nuit, sans autre véhicule devant ou en face, vous utilisez :",o:["Les feux de position uniquement","Les feux de croisement","Les feux de route","Les feux antibrouillard avant"],r:[2],x:"La nuit sans autre véhicule = feux de route (portée 150 m). Passez en feux de croisement à l'approche d'un véhicule.",tip:"🌙 Feux de route = sécurité. Faites-en l'habitude sur les routes sombres sans trafic."},
{c:"Conduite",e:"🏁",d:1,m:false,q:"Sur autoroute à plusieurs voies, la voie de gauche est :",o:["La voie la plus rapide, on peut y rester","Réservée au dépassement uniquement","La voie prioritaire pour les poids lourds","Une voie conseillée"],r:[1],x:"La voie de gauche sur autoroute est UNIQUEMENT pour dépasser. Y rester sans dépasser = amende 135 € + retrait 1 point.",tip:"⬅️ Après le dépassement → voie de droite immédiatement. C'est la loi."},
{c:"Conduite",e:"⛰️",d:2,m:false,q:"Le dépassement est interdit dans les 100 m avant un virage ou sommet de côte :",o:["Sauf si la visibilité est bonne","Sauf si vous avez le clignotant","Toujours, sans aucune exception","Sauf sur route à 2×2 voies"],r:[2],x:"Dépassement interdit 100 m avant virage, sommet de côte ou zone à visibilité insuffisante. Règle absolue, sans exception.",tip:"⛰️ Règle d'or : si vous ne voyez pas 150 m devant → ne dépassez pas."},
{c:"Conduite",e:"📐",d:2,m:false,q:"À 50 km/h sur sol sec, la distance d'arrêt totale est d'environ :",o:["10 mètres","25 mètres","38 mètres","60 mètres"],r:[2],x:"À 50 km/h : ~14 m (temps de réaction 1s) + ~25 m (freinage) ≈ 38 m au total. Doublée sur sol mouillé.",tip:"📐 Formule : distance freinage ≈ (vitesse)²/170 sur sec. Mémorisez les ordres de grandeur."},
{c:"Conduite",e:"⚠️",d:1,m:false,q:"Les feux de détresse (warnings) doivent être utilisés :",o:["Pour se garer en double file provisoirement","Pour signaler un danger imminent ou un arrêt forcé","Pour remercier un conducteur","En cas de pluie modérée"],r:[1],x:"Feux de détresse = signalement de danger uniquement : panne, accident, bouchon soudain. Mauvais usage = amende.",tip:"⚠️ Warnings ≠ 'je fais n'importe quoi'. Réservés aux vraies urgences."},
{c:"Conduite",e:"🚗",d:2,m:false,q:"Deux véhicules arrivent en même temps à une intersection non signalisée :",o:["Le plus rapide passe","Le véhicule de droite est prioritaire","Le plus gros passe","Le premier freiné cède"],r:[1],x:"Priorité à droite : à toute intersection non signalisée, le véhicule venant de votre droite est prioritaire.",tip:"➡️ Priorité à droite = la règle par défaut. Simple et universelle en France."},

// ── AUTOROUTE (9) ───────────────────────────────────────────────────
{c:"Autoroute",e:"🏎️",s:"bau",d:2,m:true,q:"La bande d'arrêt d'urgence (BAU) est réservée à :",o:["Les véhicules lents","Les arrêts d'urgence (panne, malaise, urgence)","Les cyclistes","Laisser passer les véhicules prioritaires","Le covoiturage"],r:[1,3],x:"La BAU est réservée aux pannes, urgences médicales et pour laisser passer les véhicules prioritaires. S'y arrêter sans raison = amende + retrait 3 points.",tip:"🚨 BAU = dernier recours. S'y arrêter vous expose à un risque mortel de collision."},
{c:"Autoroute",e:"➡️",d:2,m:false,q:"Pour s'insérer sur l'autoroute depuis la voie d'accélération :",o:["Vous avez la priorité","Vous cédez le passage aux véhicules sur l'autoroute","Le plus rapide passe en premier","Il faut s'arrêter et attendre un créneau"],r:[1],x:"Sur voie d'accélération : accélérez pour atteindre la vitesse de l'autoroute, insérez-vous dans un créneau. Vous cédez le passage.",tip:"⚡ Accélérez sur la voie d'accélération ! S'insérer lentement est dangereux pour tout le monde."},
{c:"Autoroute",e:"⏱️",d:2,m:false,q:"La règle des '2 secondes' sur autoroute signifie :",o:["Faire une pause toutes les 2h","Maintenir 2 secondes de distance avec le véhicule devant","Doubler en moins de 2 secondes","Klaxonner 2 secondes avant de doubler"],r:[1],x:"2 secondes de distance minimum entre vous et le véhicule devant. Repère : quand il dépasse un poteau, comptez 2s avant de le dépasser.",tip:"⏱️ Par mauvais temps : portez à 4 secondes. Sur sol mouillé, distance doublée."},
{c:"Autoroute",e:"⬅️",d:1,m:false,q:"La voie de gauche sur une autoroute à 3 voies :",o:["Permet de rouler à la vitesse souhaitée","Est réservée au dépassement uniquement","Est la voie la plus sûre","Est interdite aux camions et autorisée à tous"],r:[1],x:"Voie gauche = dépassement uniquement. Réintégrez la voie de droite après le dépassement. Sanctionné si vous y restez.",tip:"✅ Bonne pratique : toujours sur la voie de droite, voie du milieu si besoin, gauche pour doubler."},
{c:"Autoroute",e:"🛑",d:2,m:true,q:"En cas de panne sur autoroute, la procédure correcte est :",o:["Rester dans le véhicule sur la BAU","Mettre les feux de détresse immédiatement","Enfiler le gilet fluorescent avant de sortir","Poser le triangle à au moins 150 m en amont","Appeler le 15, 17, 18 ou le 112"],r:[1,2,3,4],x:"Protocole autoroute : feux de détresse → sortir par la droite → gilet → triangle 150-200 m → glissières → appel secours.",tip:"⛽ Évitez la panne : surveillez votre jauge et n'attendez pas le dernier moment !"},
{c:"Autoroute",e:"↩️",d:1,m:false,q:"Vous avez raté votre sortie sur l'autoroute. Vous devez :",o:["Reculer sur la BAU jusqu'à la sortie","Faire demi-tour sur la chaussée","Continuer jusqu'à la prochaine sortie","Vous arrêter et attendre les secours"],r:[2],x:"Demi-tour et marche arrière sont STRICTEMENT INTERDITS sur autoroute. Continuez jusqu'à la prochaine sortie.",tip:"🗺️ Utilisez un GPS. En cas d'erreur, le prochain échangeur est généralement à 5-10 km."},
{c:"Autoroute",e:"🚶",d:2,m:false,q:"Marcher sur l'autoroute (chaussée ou BAU) est :",o:["Autorisé sur la BAU","Interdit sauf urgence absolue","Autorisé avec un gilet fluorescent","Autorisé entre les bretelles"],r:[1],x:"Marcher sur l'autoroute est interdit et extrêmement dangereux. En cas de panne, placez-vous derrière les glissières.",tip:"⚠️ Derrière les glissières = seule zone sûre. Jamais sur la chaussée ni la BAU."},
{c:"Autoroute",e:"💡",s:"tunnel",d:2,m:true,q:"Dans un tunnel, vous devez obligatoirement :",o:["Allumer les feux de croisement","Maintenir une distance de sécurité accrue","Interdire tout dépassement","Réduire la vitesse de 20 km/h","Klaxonner à l'entrée"],r:[0,1],x:"Tunnel : feux de croisement obligatoires (même en plein jour) et distance de sécurité accrue (arrêt total impossible sur toute la longueur).",tip:"🚇 En cas d'incident dans un tunnel : feux, avertisseurs, sortez par la droite, suivez les issues de secours."},
{c:"Autoroute",e:"🚨",d:3,m:true,q:"Le 'couloir de vie' (en cas de bouchon soudain sur autoroute) :",o:["Se forme entre les voies 1 et 2","Permet aux secours de circuler","Est obligatoire dès l'arrêt du trafic","Peut être formé sur routes express","Est formé par les véhicules serrés à gauche et à droite"],r:[0,1,2,3,4],x:"Couloir de vie : véhicules voie 1 serrent à gauche, autres serrent à droite. Libère un couloir pour les secours. Obligatoire sur autoroutes et voies express.",tip:"🚑 Couloir de vie = obligation légale depuis 2021. Amende 135 € si non-respect."},

// ── DOCUMENTS (7) ───────────────────────────────────────────────────
{c:"Documents",e:"🔧",d:1,m:false,q:"Le contrôle technique est obligatoire :",o:["Tous les ans","À 4 ans puis tous les 2 ans","Tous les 4 ans","Tous les 5 ans"],r:[1],x:"Premier CT à 4 ans d'immatriculation, puis tous les 2 ans. En cas de vente, CT de moins de 6 mois obligatoire.",tip:"🔧 CT dépassé = amende 135 € + immobilisation du véhicule possible."},
{c:"Documents",e:"🛡️",d:1,m:false,q:"L'assurance minimum légale pour circuler est :",o:["La responsabilité civile (RC)","La tous risques","La garantie conducteur","La protection juridique"],r:[0],x:"La RC (responsabilité civile) est le minimum légal obligatoire. Elle couvre les dommages causés aux tiers. Circuler sans = délit.",tip:"🛡️ RC = votre responsabilité envers les autres. Ne couvre PAS vos propres dommages."},
{c:"Documents",e:"📋",d:2,m:false,q:"La durée de validité du permis de conduire B (adulte) est de :",o:["5 ans","10 ans","15 ans","À vie (illimité)"],r:[2],x:"Depuis 2013, le permis B est valable 15 ans pour les adultes. Renouvellement obligatoire à expiration.",tip:"📅 Depuis 2013, uniformisation européenne : 15 ans pour permis B adulte."},
{c:"Documents",e:"🚗",d:2,m:false,q:"En cas de vente, le nouveau propriétaire doit faire la carte grise dans :",o:["7 jours","15 jours","1 mois","3 mois"],r:[1],x:"Le nouveau propriétaire dispose de 15 jours pour demander la carte grise. Le vendeur doit déclarer la cession immédiatement sur l'ANTS.",tip:"🖥️ Déclaration de cession = obligatoire dès la vente sur ants.gouv.fr. Sans ça, les amendes tombent sur vous !"},
{c:"Documents",e:"🌿",s:"crit_air",d:2,m:false,q:"La vignette Crit'Air de niveau 1 (verte) correspond à :",o:["Les véhicules électriques","Les véhicules essence Euro 5 ou 6 et hybrides","Les véhicules diesel récents","Les deux-roues modernes"],r:[1],x:"Crit'Air 1 (vert) : essence Euro 5-6 et hybrides. Crit'Air E (vert foncé) : 100 % électriques et hydrogène. Les ZFE restreignent l'accès selon la vignette.",tip:"🌿 Crit'Air E > 1 > 2 > 3 > 4 > 5 (du moins polluant au plus polluant)."},
{c:"Documents",e:"⚠️",d:2,m:false,q:"Circuler sans assurance expose à :",o:["Une contravention de 3e classe","Un délit : amende jusqu'à 3 750 €, suspension/annulation de permis","Seulement une mise en garde","Une amende forfaitaire de 135 €"],r:[1],x:"Défaut d'assurance = DÉLIT. Amende jusqu'à 3 750 €, suspension ou annulation du permis, confiscation du véhicule, TIG.",tip:"🚫 Depuis 2019, les radars automatiques peuvent détecter les non-assurés. Pas de pitié !"},
{c:"Documents",e:"📝",d:2,m:false,q:"En cas d'accident, le constat amiable doit être signé :",o:["Seulement par le responsable","Par les deux conducteurs impliqués","Seulement s'il y a des blessés","Par un témoin obligatoirement"],r:[1],x:"Le constat amiable doit être signé des DEUX conducteurs. À envoyer à l'assureur sous 5 jours ouvrés. Désaccord = cochez 'désaccord'.",tip:"✍️ Ne refusez jamais de signer ! Signez avec 'désaccord' si vous contestez."},

// ── ÉCLAIRAGES (8) ──────────────────────────────────────────────────
{c:"Éclairages",e:"💡",d:2,m:false,q:"Les feux de route (pleins phares) ont une portée d'environ :",o:["40 mètres","80 mètres","150 mètres","300 mètres"],r:[2],x:"Feux de route ≈ 150 m. Feux de croisement ≈ 30-40 m. Feux de route obligatoires la nuit sans autre véhicule.",tip:"💡 150 m à 90 km/h = 6 secondes de réaction. Feux de route = confort et sécurité."},
{c:"Éclairages",e:"🚇",s:"tunnel",d:1,m:false,q:"Dans un tunnel, même en plein jour, vous allumez :",o:["Uniquement les feux de position","Les feux de croisement","Les feux de route","Aucun feu si le tunnel est éclairé"],r:[1],x:"Feux de croisement obligatoires dans tout tunnel, même éclairé et même en journée. Amende 35 € en cas d'infraction.",tip:"🚇 Tunnel = feux de croisement. Toujours. Même en plein soleil."},
{c:"Éclairages",e:"🌫️",d:2,m:false,q:"Les feux antibrouillard arrière doivent être utilisés uniquement :",o:["Dès qu'il pleut","La nuit uniquement","Quand la visibilité est inférieure à 50 m","Sur autoroute uniquement"],r:[2],x:"Antibrouillard arrière : uniquement si visibilité < 50 m (brouillard dense, neige). Les utiliser autrement éblouit les conducteurs.",tip:"🌫️ Feux antibrouillard mal utilisés = infraction. Ils éblouissent et gênent derrière vous."},
{c:"Éclairages",e:"🔆",d:2,m:false,q:"Rouler avec les seuls feux de position (veilleuses) la nuit est :",o:["Autorisé si la route est bien éclairée","Interdit sur toutes les routes","Autorisé en agglomération éclairée","Autorisé à moins de 30 km/h"],r:[1],x:"Les feux de position seuls sont INTERDITS la nuit sur route. Leur portée est insuffisante pour assurer la visibilité.",tip:"🔆 Veilleuses = signalisation à l'arrêt uniquement (parking, attente). Pas pour rouler."},
{c:"Éclairages",e:"→",d:1,m:false,q:"Le clignotant doit être actionné :",o:["Au moment de la manœuvre","Avant la manœuvre, pour prévenir les autres usagers","Après la manœuvre pour confirmation","Uniquement pour les changements de voie importants"],r:[1],x:"Clignotant AVANT la manœuvre = prévenir les autres. L'actionner pendant ou après n'a aucune utilité préventive.",tip:"→ Clignotant = intention. Rétro + angle mort + clignotant + manœuvre. Dans cet ordre."},
{c:"Éclairages",e:"⚠️",d:1,m:false,q:"Les feux de détresse (warnings) s'utilisent pour :",o:["Se garer en double file","Signaler un danger imminent ou un véhicule arrêté en urgence","Remercier un conducteur","En cas de pluie forte"],r:[1],x:"Feux de détresse = signalement de danger réel uniquement : panne, accident, bouchon soudain, ralentissement brutal.",tip:"⚠️ Warnings ≠ 'pause stationnement illicite'. Leur usage abusif nuit à leur efficacité."},
{c:"Éclairages",e:"🔄",d:2,m:false,q:"En quittant un giratoire, vous devez actionner :",o:["Le clignotant gauche","Le clignotant droit","Aucun clignotant n'est nécessaire","Les feux de détresse"],r:[1],x:"En quittant un giratoire : clignotant DROIT pour signaler votre sortie aux véhicules en attente d'entrer.",tip:"🔄 Entrer dans un giratoire = pas de clignotant. Sortir = clignotant droit."},
{c:"Éclairages",e:"🌙",d:1,m:false,q:"Vous croisez un véhicule la nuit. Vous passez en feux de croisement :",o:["Uniquement si l'autre conduit en feux de route","Dès qu'un autre véhicule approche en face ou devant","Seulement sur autoroute","À 200 m exactement"],r:[1],x:"Feux de croisement obligatoires dès qu'un véhicule approche en face ou que vous en suivez un. Pour ne pas éblouir.",tip:"🌙 S'éblouir mutuellement = cécité temporaire à 130 km/h. Croisez en code !"},

// ── ENVIRONNEMENT (8) ───────────────────────────────────────────────
{c:"Environnement",e:"🌿",d:2,m:false,q:"Une Zone à Faibles Émissions (ZFE) est :",o:["Une zone sans limitation de vitesse","Une zone où l'accès est restreint selon la vignette Crit'Air","Une zone réservée aux véhicules électriques","Un périmètre scolaire"],r:[1],x:"Les ZFE (grandes agglomérations) limitent l'accès aux véhicules les plus polluants selon leur vignette Crit'Air.",tip:"🌿 En 2025, de nombreuses métropoles françaises ont des ZFE. Vérifiez votre vignette !"},
{c:"Environnement",e:"⚡",d:2,m:false,q:"La vignette Crit'Air 'E' (fond vert foncé) est réservée aux :",o:["Véhicules hybrides","Véhicules 100 % électriques et à hydrogène","Véhicules essence Euro 6","Véhicules de catégorie 1"],r:[1],x:"Crit'Air E = véhicules 100 % électriques ou à hydrogène. Toujours autorisé dans les ZFE.",tip:"⚡ Crit'Air E = meilleure classification. Toujours autorisé dans toutes les ZFE."},
{c:"Environnement",e:"🌱",d:2,m:true,q:"La conduite éco-responsable permet de :",o:["Réduire la consommation de carburant","Diminuer les émissions de CO2","Réduire l'usure des freins et pneus","Améliorer la sécurité par l'anticipation","Diminuer les nuisances sonores"],r:[0,1,2,3,4],x:"L'éco-conduite (anticipation, vitesse stabilisée, frein moteur) réduit consommation, usure, CO2 et améliore la sécurité.",tip:"🌱 10 à 15 % de carburant économisé avec l'éco-conduite. Bon pour le portefeuille et la planète !"},
{c:"Environnement",e:"🛣️",d:3,m:false,q:"Les voies réservées au covoiturage (signalées par un losange) :",o:["Sont accessibles à tous","Sont réservées aux véhicules avec au moins 2 personnes","Sont réservées aux taxis et bus","Ne sont actives que la nuit"],r:[1],x:"Voies covoiturage (losange blanc) : minimum 2 personnes à bord (parfois 3). Présentes sur certains axes d'Île-de-France, Lyon, Grenoble.",tip:"🚗 Covoiturage = moins de véhicules, moins de pollution, moins d'embouteillages."},
{c:"Environnement",e:"🚗",d:2,m:false,q:"Laisser tourner son moteur à l'arrêt plus d'une minute est :",o:["Recommandé pour chauffer le moteur","Interdit par arrêté municipal dans de nombreuses communes","Uniquement interdit dans les parkings fermés","Autorisé en hiver pour le dégivrage"],r:[1],x:"Le moteur tournant à l'arrêt pollue inutilement. De nombreuses communes l'interdisent (arrêté). Coupez le moteur dès > 1 min d'arrêt.",tip:"🚗 Moteur à froid = couper dès que possible. Les voitures modernes ne nécessitent pas de 'chauffage'."},
{c:"Environnement",e:"🔵",d:2,m:false,q:"Des pneus sous-gonflés (pression insuffisante) entraînent :",o:["Une meilleure adhérence","Surconsommation de carburant et usure accrue","Uniquement un meilleur confort","Aucun effet sur la consommation"],r:[1],x:"Pneus sous-gonflés de 0,5 bar : +2 % de consommation, échauffement excessif, risque d'éclatement.",tip:"🔵 Vérifiez la pression tous les mois à froid (avant de rouler)."},
{c:"Environnement",e:"🚫",d:2,m:false,q:"Dans une ZFE, un véhicule sans vignette Crit'Air ou Crit'Air 5 :",o:["Peut circuler avec autorisation spéciale","Est soumis à une amende s'il circule dans la zone aux heures d'application","N'est soumis qu'à une restriction horaire","Est autorisé le week-end"],r:[1],x:"Véhicule non classé ou Crit'Air 5 : interdit dans la plupart des ZFE aux heures de restriction. Amende 68 € (voiture) à 135 € (PL).",tip:"🚫 Vérifiez l'application des ZFE de votre commune : horaires, périmètre, exceptions."},
{c:"Environnement",e:"🌍",d:2,m:false,q:"Une conduite fluide et anticipatrice réduit les émissions d'environ :",o:["1 à 2 %","10 à 15 %","25 à 40 %","Plus de 50 %"],r:[1],x:"Conduite fluide et anticipatrice : -10 à 15 % de consommation et d'émissions. Évitez accélérations et freinages brusques.",tip:"🌍 Anticipez les ralentissements : lever le pied tôt = frein moteur = économie de carburant."},
,

// ── SIGNALISATION — suite (15) ────────────────────────────────────
{c:"Signalisation",e:"🛑",d:2,m:false,q:"Un panneau 'Cédez le passage' complété d'un panonceau 'Sauf riverains' signifie :",o:["Les riverains ont la priorité absolue","Les riverains peuvent ne pas céder le passage","Tout le monde doit céder","La signalisation ne s'applique qu'aux camions"],r:[1],x:"Les pannonceaux 'Sauf' créent une exception à la règle principale. Les riverains identifiés sont exemptés de l'obligation.",tip:"📌 Panonceau = information complémentaire. 'Sauf' = exception à la règle du panneau principal."},
{c:"Signalisation",e:"🔵",d:1,m:false,q:"Un panneau carré bleu avec une flèche blanche courbée vers la droite signifie :",o:["Recommandation de tourner à droite","Obligation de tourner à droite","Voie autorisée à droite","Danger à droite"],r:[1],x:"Panneaux ronds bleus = obligations de direction. Carré bleu = indication. Ici rond bleu avec flèche = obligation de direction.",tip:"🔵 Rond bleu = OBLIGATION. Carré bleu = INDICATION. La forme change tout !"},
{c:"Signalisation",e:"⚠️",d:2,m:false,q:"Un panneau triangulaire 'dos d'âne' ou 'cassis' annonce :",o:["Une montée douce","Un ralentisseur ou une rupture de chaussée","Un passage à niveau","Une route cahoteuse"],r:[1],x:"Le panneau 'dos d'âne' (bosse) ou 'cassis' (creux) signale un ralentisseur ou une déformation brusque de la chaussée.",tip:"⛰️ Dos d'âne ou cassis = ralentir impérativement. Les suspensions et le bas de caisse en dépendent."},
{c:"Signalisation",e:"🏁",d:2,m:false,q:"Le panneau 'fin de toutes interdictions' (cercle blanc avec bandes grises) :",o:["Annule uniquement l'interdiction de vitesse","Annule toutes les interdictions édictées par des panneaux précédents","Marque la fin d'une agglomération","Annule la priorité à droite"],r:[1],x:"Ce panneau annule toutes les restrictions instaurées par des panneaux précédents (vitesse, dépassement, klaxon…) mais pas la signalisation permanente.",tip:"⭕ 'Fin de toutes interdictions' ≠ fin de la priorité à droite. Celle-ci redevient la règle par défaut."},
{c:"Signalisation",e:"🟦",d:2,m:false,q:"Un panneau rectangulaire bleu avec un 'P' blanc et une flèche indique :",o:["Un parking payant uniquement","La direction d'un parking","Un parking réservé aux handicapés","Un parking de covoiturage"],r:[1],x:"Les panneaux bleus rectangulaires avec flèche sont des panneaux de direction. Le 'P' avec flèche indique la direction d'un parking.",tip:"🅿️ Les panneaux de direction sont toujours rectangulaires et ont une flèche directionnelle."},
{c:"Signalisation",e:"🚧",d:2,m:false,q:"Des cônes orange sur la chaussée avec voie rétrécie indiquent :",o:["Un chantier : ralentissez et respectez la signalisation temporaire","Une piste cyclable temporaire","Une zone de test routier","Une déviation obligatoire"],r:[0],x:"Signalisation temporaire de chantier : cônes orange, panneaux fond orange. Valeur identique aux panneaux permanents. Adaptez la vitesse.",tip:"🚧 Orange = temporaire (travaux). Même force juridique que les panneaux blancs permanents."},
{c:"Signalisation",e:"🔴",d:2,m:false,q:"La ligne blanche continue au bord de la chaussée (ligne de rive) :",o:["Interdit de circuler dessus","Sépare la chaussée du bas-côté, ne peut être franchie que pour un arrêt d'urgence","Est réservée aux cyclistes","N'a aucune valeur réglementaire"],r:[1],x:"La ligne de rive délimite la chaussée du bas-côté. Elle ne peut être franchie que pour s'arrêter en urgence ou laisser le passage.",tip:"↔️ Ligne de rive blanche = bord de chaussée. Franchir = sortir de la route."},
{c:"Signalisation",e:"⚠️",d:3,m:false,q:"Un panneau de passage à niveau SANS barrières (croix de Saint-André) :",o:["Signifie que le passage est sécurisé","Oblige à s'arrêter avant les rails","Impose une vigilance maximale : pas de barrières pour avertir","N'existe plus en France"],r:[2],x:"Passage à niveau sans barrières = danger maximal. Pas de protection mécanique. Regardez dans les deux sens avant de traverser.",tip:"⚠️ En France, il existe encore des PN sans barrières. Beaucoup d'accidents mortels y ont lieu."},
{c:"Signalisation",e:"🔵",d:1,m:false,q:"Le panneau 'sens unique' est :",o:["Un panneau rectangulaire bleu avec flèche blanche","Un panneau rond blanc avec flèche noire","Un panneau carré blanc","Un panneau vert avec flèche"],r:[0],x:"Le sens unique est signalé par un panneau rectangulaire bleu avec une flèche blanche. Il interdit la circulation en sens inverse.",tip:"🔵 Bleu rectangulaire + flèche blanche = indication de sens unique. Très courant en ville."},
{c:"Signalisation",e:"🏁",d:2,m:false,q:"Balises blanches et rouges au bord de la route (bornes kilométriques alternées) :",o:["Blanc à gauche, rouge à droite dans le sens de la marche","Délimitent les zones à risque","Indiquent les sorties d'autoroute","Signalent les points kilométriques pairs"],r:[0],x:"Les balises de rive sont blanches à gauche (côté gauche) et rouges à droite dans le sens de la circulation. Utile pour s'orienter dans le brouillard.",tip:"🔴 Rouge à droite = bonne direction. Blanc à gauche = sens de circulation normale."},
{c:"Signalisation",e:"🅿️",d:2,m:false,q:"Un panneau 'stationnement alterné' (B6a1) avec panonceau '1-15' :",o:["Autorise le stationnement tous les jours","Indique le stationnement autorisé du 1 au 15 du mois côté panneau","Autorise le stationnement les jours impairs","S'applique uniquement aux résidents"],r:[1],x:"Stationnement alterné semi-mensuel : du 1 au 15 d'un côté, du 16 à la fin du mois de l'autre côté. Changement de côté à 20h30.",tip:"📅 Changement à 20h30 la veille. Ex : le 15 au soir (20h30) → passez de l'autre côté."},
{c:"Signalisation",e:"⚡",d:2,m:false,q:"Un feu tricolore à flèche verte fixe (pas clignotante) pour tourner :",o:["Autorise la manœuvre avec priorité absolue","N'existe pas en France","Autorise le mouvement, vous restez prioritaire","Autorise sans priorité comme la flèche clignotante"],r:[2],x:"Flèche verte fixe = vous pouvez effectuer la manœuvre indiquée avec priorité sur les autres. Différent de la flèche clignotante (cédez le passage).",tip:"→ Fixe = prioritaire. Clignotante = cédez. La différence est fondamentale !"},
{c:"Signalisation",e:"🚦",d:3,m:true,q:"Un feu rouge avec une flèche jaune clignotante vers la droite :",o:["Interdit de tourner à droite","Autorise le tourne-à-droite pour les cyclistes uniquement","Autorise le tourne-à-droite en cédant le passage aux piétons","Autorise les bus et taxis uniquement"],r:[1,2],x:"Depuis 2012, la flèche jaune clignotante autorise les cyclistes à passer au rouge (tourne-à-droite ou tout-droit vers une voie cyclable), en cédant aux piétons.",tip:"🚲 Flèche jaune = spécifique aux cyclistes. Les voitures restent au rouge."},
{c:"Signalisation",e:"🔶",d:2,m:false,q:"Le losange jaune barré d'un trait noir diagonal signifie :",o:["Attention, route dangereuse","Fin de votre priorité : vous redevenez soumis à la règle générale","Début d'une zone prioritaire","Danger de glissance"],r:[1],x:"Losange jaune barré = FIN de la priorité. Vous n'êtes plus sur route prioritaire. Appliquez la règle générale (priorité à droite).",tip:"🔶 Non barré = route prioritaire. Barré = fin. Toujours regarder s'il y a une barre !"},
{c:"Signalisation",e:"🏙️",d:1,m:false,q:"Le panneau d'entrée d'agglomération est :",o:["Un panneau triangulaire rouge","Un panneau rectangulaire blanc avec le nom de la ville en lettres noires","Un panneau bleu avec le nom de la ville","Un panneau vert sur autoroute"],r:[1],x:"L'entrée d'agglomération est signalée par un panneau rectangulaire blanc (nom de ville fond blanc, lettres noires). La limite de 50 km/h s'applique dès ce panneau.",tip:"🏙️ Panneau blanc = agglomération → 50 km/h. Panneau barré = fin agglomération."},

// ── PRIORITÉS — suite (8) ────────────────────────────────────────
{c:"Priorités",e:"🚌",d:2,m:false,q:"Un car scolaire est arrêté, feux de détresse allumés, signal d'arrêt déployé. Vous devez :",o:["Ralentir à 25 km/h et passer prudemment","Vous arrêter et ne repartir que quand le car repart ou quand le signal est replié","Klaxonner pour prévenir les enfants","Dépasser par la gauche rapidement"],r:[1],x:"Car scolaire avec signal d'arrêt déployé = STOP absolu. Les enfants peuvent traverser. Attendez que le signal soit replié.",tip:"🚌 Signal d'arrêt déployé (bras rouge) = interdit de dépasser. C'est comme un feu rouge."},
{c:"Priorités",e:"🚑",d:1,m:false,q:"Les véhicules prioritaires (gyrophare + sirène) comprennent :",o:["Uniquement les ambulances SAMU","Police, gendarmerie, pompiers, SAMU, douanes en mission","Tous les véhicules avec gyrophare","Les taxis en urgence"],r:[1],x:"Véhicules prioritaires en mission : police, gendarmerie, pompiers, SAMU, douanes. Les autres (taxis, dépanneurs…) ne le sont pas même avec gyrophare.",tip:"🚔 Gyrophare seul (sans sirène) = priorité légale incomplète. Les deux ensemble = priorité totale."},
{c:"Priorités",e:"🚗",d:2,m:false,q:"Vous êtes sur une voie sans issue et voulez sortir. Une voiture arrive sur la route principale :",o:["Vous êtes prioritaire car vous sortez d'une voie plus étroite","Vous cédez : tout sortant de voie sans issue cède le passage","Priorité à droite classique","Le premier arrivé passe"],r:[1],x:"Quiconque sort d'une voie sans issue, d'un chemin, d'un parking ou d'une propriété privée CÈDE toujours le passage.",tip:"🏠 Propriété privée → voie publique = TOUJOURS céder. Parking, voie sans issue, chemin."},
{c:"Priorités",e:"🔄",d:3,m:false,q:"Un giratoire SANS panneau 'Cédez le passage' à l'entrée fonctionne avec :",o:["La priorité à droite (véhicules entrant sont prioritaires)","La même règle que les giratoires signalisés","La priorité au plus gros véhicule","La signalisation interne du giratoire"],r:[0],x:"Sans signalisation, la priorité à droite s'applique : les véhicules entrant (à droite du véhicule dans le giratoire) sont prioritaires. Très rare aujourd'hui.",tip:"🔄 Giratoire non signalisé = ancien système, priorité à ceux qui entrent. Rarissime mais au programme !"},
{c:"Priorités",e:"🚲",d:2,m:false,q:"À une piste cyclable traversant une route secondaire, les cyclistes :",o:["Cèdent toujours le passage aux voitures","Sont prioritaires si la piste est marquée et signalée comme prioritaire","Doivent s'arrêter systématiquement","Sont prioritaires uniquement si le feu est vert"],r:[1],x:"Si la piste cyclable est signalée prioritaire (passage, marquage), les cyclistes ont la priorité. Sinon, priorité à droite normale.",tip:"🚲 Piste cyclable prioritaire = signalisation spécifique (passage peint, panneau). Vérifiez avant de couper."},
{c:"Priorités",e:"🏎️",d:2,m:false,q:"Sur autoroute avec voie de décélération (sortie), qui est prioritaire ?",o:["Le véhicule qui sort (sur la voie de décélération)","Les véhicules continuant sur l'autoroute","Priorité à droite","Le plus rapide"],r:[0],x:"Le véhicule s'engageant sur la voie de décélération pour sortir est sur sa propre voie. Il ne gêne pas les voitures qui continuent.",tip:"➡️ Voie de décélération = déjà séparée de l'autoroute. Sortez sereinement, vous êtes sur votre voie."},
{c:"Priorités",e:"🚶",d:2,m:false,q:"Un piéton traverse hors passage piéton. Vous devez :",o:["Klaxonner pour lui signaler qu'il est en tort","Ralentir : il est vulnérable même s'il est en infraction","Le forcer à se dépêcher","Continuer normalement, il est en infraction"],r:[1],x:"Même en infraction, le piéton est vulnérable. Votre obligation de sécurité prime sur son infraction. Ralentissez.",tip:"🚶 Piéton en infraction ≠ piéton sans protection. Votre responsabilité pénale est engagée en cas d'accident."},
{c:"Priorités",e:"🚜",d:2,m:false,q:"Un convoi agricole (tracteur + remorque) roule lentement. Vous pouvez le dépasser :",o:["Uniquement avec son accord","Comme tout autre véhicule lent, en respectant les règles de dépassement","Jamais, les engins agricoles sont protégés","Par la droite uniquement"],r:[1],x:"Un convoi agricole se dépasse comme tout autre véhicule lent : ligne discontinue, bonne visibilité, par la gauche.",tip:"🚜 Les engins agricoles sont souvent larges. Dépassez avec une marge suffisante et assurez-vous d'être bien visible avant de vous rabattre."},

// ── VITESSE — suite (8) ─────────────────────────────────────────
{c:"Vitesse",e:"💨",d:2,m:false,q:"Sur une route nationale à 2×2 voies avec terre-plein central, hors agglomération, la limitation est :",o:["80 km/h","90 km/h","110 km/h","130 km/h"],r:[2],x:"Route à 2×2 voies avec séparateur central (hors autoroute) = voie express → 110 km/h. Réduit à 100 km/h par pluie.",tip:"🛣️ Séparateur central + 2×2 voies hors autoroute = 110 km/h. C'est la voie express."},
{c:"Vitesse",e:"🚧",d:2,m:false,q:"Dans une zone de travaux avec limitation à 70 km/h, la limitation s'applique :",o:["Uniquement quand des ouvriers sont présents","Uniquement de nuit","En permanence, même sans ouvrier visible","Uniquement si un agent de signalisation est présent"],r:[2],x:"La signalisation temporaire de chantier s'applique 24h/24, 7j/7, que des ouvriers soient présents ou non.",tip:"🚧 Respect obligatoire même chantier vide. Les panneaux ont force de loi jusqu'à leur retrait."},
{c:"Vitesse",e:"⚡",d:3,m:true,q:"Les facteurs aggravant le risque d'accident à haute vitesse sont :",o:["L'augmentation exponentielle de la distance de freinage","L'élargissement de l'angle mort","La réduction du temps de réaction utile","L'augmentation de l'énergie cinétique (×4 si vitesse ×2)","La diminution du champ visuel périphérique"],r:[0,2,3,4],x:"À vitesse double : énergie cinétique ×4, freinage ×4, temps de réaction insuffisant, champ visuel réduit. L'angle mort n'est pas lié à la vitesse.",tip:"⚡ Énergie cinétique = ½mv². Si v double, énergie ×4. La physique est implacable."},
{c:"Vitesse",e:"🏘️",d:2,m:false,q:"Un panneau de vitesse recommandée (chiffre sans liseré rouge) :",o:["A la même valeur qu'un panneau réglementaire","Est une simple suggestion, non obligatoire","Est obligatoire uniquement par mauvais temps","N'existe pas en France"],r:[1],x:"Les panneaux de vitesse recommandée (fond jaune ou sans liseré rouge) sont indicatifs. Pas de sanction en cas de dépassement, sauf si la vitesse devient dangereuse.",tip:"💛 Jaune = recommandation. Blanc + rouge = limitation. La couleur et le liseré font la différence."},
{c:"Vitesse",e:"🌙",d:2,m:false,q:"La nuit, sur route non éclairée, les feux de croisement permettent de voir à :",o:["150 mètres","80 mètres","30-40 mètres","60 mètres"],r:[2],x:"Feux de croisement : portée 30-40 m. Or à 90 km/h, la distance d'arrêt est de ~75 m. D'où l'utilité des feux de route la nuit.",tip:"🌙 Feux de croisement la nuit à 90 km/h = conduire 'dans ses phares'. Passez en feux de route !"},
{c:"Vitesse",e:"📱",d:2,m:false,q:"Utiliser un GPS tenu en main pendant la conduite est :",o:["Autorisé si l'écran est placé correctement","Interdit comme le téléphone tenu en main","Autorisé s'il est posé sur le tableau de bord","Autorisé uniquement sur autoroute"],r:[1],x:"Tenir tout appareil en main en conduisant est interdit. Le GPS doit être fixé sur un support. Amende 135 € + 3 points.",tip:"📱 Tout appareil tenu en main = infraction. GPS, téléphone, tablette : tous concernés."},
{c:"Vitesse",e:"🚗",d:2,m:false,q:"À quelle vitesse la distance d'arrêt sur sol sec dépasse-t-elle 100 mètres ?",o:["À 80 km/h","À 90 km/h","À 110 km/h","À 130 km/h"],r:[2],x:"À 110 km/h sur sol sec : ~30 m (réaction 1s) + ~75 m (freinage) ≈ 105 m. À 130 km/h ≈ 130 m.",tip:"📐 Formule approximative : distance totale ≈ vitesse × 1,2 sur sec, × 2,4 sur mouillé."},
{c:"Vitesse",e:"🛑",d:3,m:false,q:"Un radar pédagogique (qui affiche votre vitesse sans vous flasher) :",o:["Remplace légalement un radar fixe","A une valeur informative mais ne verbalise pas","Est uniquement placé devant les écoles","Peut déclencher un contrôle policier"],r:[1],x:"Les radars pédagogiques affichent votre vitesse pour vous inciter à ralentir. Aucune verbalisation directe.",tip:"💡 Radar pédagogique = miroir de votre conduite. Pas d'amende, mais données parfois utilisées pour placer un radar fixe."},

// ── ALCOOL — suite (8) ──────────────────────────────────────────
{c:"Alcool",e:"⏰",d:2,m:false,q:"À quelle vitesse l'organisme élimine-t-il l'alcool en moyenne ?",o:["0,10 à 0,15 g/L par heure","0,50 g/L par heure","1 g/L par heure","Cela dépend uniquement du sexe"],r:[0],x:"L'organisme élimine l'alcool à une vitesse de 0,10 à 0,15 g/L par heure en moyenne. Rien n'accélère ce processus (café, douche, sport).",tip:"⏰ Rien n'accélère l'élimination. Seul le temps fait baisser le taux. Dormez si besoin !"},
{c:"Alcool",e:"🍺",d:3,m:false,q:"Après une soirée (fin à 3h du matin, 5 verres), à 8h le lendemain matin :",o:["Vous êtes forcément sobre","Vous pouvez encore être au-dessus de la limite légale","Les 8h d'élimination suffisent toujours","Seul un test peut le confirmer, mais le café aide"],r:[1],x:"5 verres ≈ 1,25 g/L. Élimination : ~0,10-0,15 g/L/h. En 5h (3h→8h) : élimination de 0,5-0,75 g/L. Il peut rester 0,5-0,75 g/L.",tip:"🧮 Calcul : verres × 0,25 g/L ÷ élimination horaire = temps nécessaire pour atteindre 0."},
{c:"Alcool",e:"💊",d:2,m:false,q:"Un médicament de niveau 2 (pictogramme orange) : que faire avant de conduire ?",o:["Ne pas conduire du tout","Conduire normalement, le niveau 2 n'a aucun effet","Demander avis médical, réduire les activités nécessitant vigilance","Attendre 1h après la prise"],r:[2],x:"Niveau 2 (orange) : 'Soyez très prudent. Ne pas conduire sans avis médical.' L'avis du médecin ou pharmacien est indispensable.",tip:"💊 Niveaux : 1 (jaune) = prudence. 2 (orange) = avis médical. 3 (rouge) = ne pas conduire."},
{c:"Alcool",e:"🚗",d:2,m:false,q:"Vous avez consommé du cannabis il y a 10 jours. Un test salivaire peut-il vous détecter ?",o:["Non, 48h suffisent à l'élimination","Oui, le THC reste détectable jusqu'à plusieurs semaines dans la salive","Non, seul le test sanguin détecte après 48h","Uniquement si vous avez fumé régulièrement"],r:[1],x:"Le THC (cannabis) reste détectable par test salivaire plusieurs jours après consommation occasionnelle, et jusqu'à plusieurs semaines pour un usage régulier.",tip:"🌿 Cannabis et conduite : risque pénal même longtemps après la consommation. Tolérance zéro."},
{c:"Alcool",e:"⚖️",d:3,m:true,q:"Conduire sous l'emprise de stupéfiants cumulé avec de l'alcool (≥ 0,2 g/L) expose à :",o:["Les peines de chaque infraction séparément","3 ans d'emprisonnement et 9 000 € d'amende (cumul)","Un simple retrait de permis","6 ans d'emprisonnement et 150 000 € d'amende"],r:[1],x:"Cumul alcool + stupéfiants : peine portée à 3 ans d'emprisonnement et 9 000 € d'amende, plus retrait 6 points et suspension/annulation du permis.",tip:"⚖️ Cumul des infractions = aggravation des peines. Le code pénal ne plaisante pas."},
{c:"Alcool",e:"🍷",d:2,m:false,q:"L'alcoolémie 'ressentie' correspond-elle toujours à l'alcoolémie réelle ?",o:["Oui, on ressent toujours exactement son taux","Non : la tolérance, la fatigue, et le type d'alcool faussent la perception","Oui si on a mangé avant","Non uniquement pour les femmes"],r:[1],x:"La perception des effets de l'alcool est très variable selon la tolérance, la fatigue, le repas, le gabarit. L'éthylotest est le seul indicateur fiable.",tip:"🎭 Sentiment de sobriété ≠ sobriété réelle. Utilisez un éthylotest. Ne vous fiez pas à votre ressenti."},
{c:"Alcool",e:"🚔",d:2,m:false,q:"En cas de contrôle d'alcoolémie, refuser de souffler dans l'éthylotest :",o:["Est autorisé si vous êtes à jeun","Entraîne les mêmes peines que conduire avec > 0,8 g/L","N'est sanctionné que par une amende forfaitaire","Est autorisé si vous avez un justificatif médical"],r:[1],x:"Refus d'éthylomètre = même sanction que délit d'alcoolémie : 2 ans, 4 500 €, retrait 6 points, suspension de permis.",tip:"🚫 Refuser = pire que souffler et être positif. Aucun intérêt légal de refuser."},
{c:"Alcool",e:"🏎️",d:3,m:false,q:"L'alcool augmente les distances de freinage car il :",o:["Accélère le temps de réaction uniquement","Augmente le temps de réaction ET altère la coordination motrice","N'affecte que la perception des distances","N'affecte que l'équilibre, pas le freinage"],r:[1],x:"L'alcool retarde le temps de réaction (jusqu'à ×2) ET altère la coordination motrice (précision du freinage). Double effet dévastateur.",tip:"🍺 1 verre = +10-20 % de temps de réaction. 3 verres = réflexes divisés par deux ou plus."},

// ── STATIONNEMENT — suite (8) ────────────────────────────────────
{c:"Stationnement",e:"🅿️",d:2,m:false,q:"Stationner en côte avec risque de déplacement du véhicule : les roues doivent être :",o:["Dans l'axe de la route","Braquées vers le trottoir (ou la bordure) pour bloquer le véhicule","Braquées vers la route","Peu importe si le frein à main est serré"],r:[1],x:"En côte : roues braquées vers le trottoir (descente) ou vers la route (montée sans trottoir). Le frein à main seul peut céder.",tip:"🔧 En côte + trottoir : roues contre le trottoir. Sans trottoir : roues vers le fossé. +serrez le frein à main."},
{c:"Stationnement",e:"🔵",d:2,m:false,q:"La 'zone bleue' de stationnement nécessite :",o:["Un ticket de parking","L'utilisation d'un disque de stationnement indiquant votre heure d'arrivée","Un abonnement résidentiel","Aucun document, stationnement libre 2h"],r:[1],x:"Zone bleue = disque de stationnement obligatoire. Vous indiquez l'heure d'arrivée. Durée limitée (généralement 1h30 ou 2h).",tip:"🔵 Sans disque en zone bleue = amende. Le disque est disponible en pharmacie ou mairie."},
{c:"Stationnement",e:"🚫",d:2,m:false,q:"Quelle est la différence entre 'arrêt' et 'stationnement' ?",o:["Aucune différence juridique","Arrêt = immobilisation brève liée à l'activité du conducteur. Stationnement = toute immobilisation","Arrêt = moteur coupé. Stationnement = moteur allumé","Arrêt = < 5 min. Stationnement = > 5 min"],r:[1],x:"Arrêt = immobilisation brève, conducteur présent et prêt à repartir. Stationnement = toute autre immobilisation (conducteur absent, durée longue).",tip:"⏱️ Arrêt bref devant une boulangerie = arrêt. Attendre un ami 20 min = stationnement. La distinction a des conséquences légales."},
{c:"Stationnement",e:"🚒",d:1,m:false,q:"Stationner à moins de 15 m d'un feu tricolore est :",o:["Autorisé si vous restez 5 minutes maximum","Interdit car cela masque le feu aux autres usagers","Autorisé la nuit","Toléré si votre véhicule ne dépasse pas la ligne de stop"],r:[1],x:"Interdit de stationner à moins de 15 m d'un feu tricolore : risque de masquer le feu aux autres conducteurs et piétons.",tip:"🚦 15 m = environ 2,5 longueurs de voiture. Facile à sous-estimer. Garez-vous plus loin."},
{c:"Stationnement",e:"♿",d:1,m:false,q:"Une place de stationnement réservée aux personnes handicapées peut être utilisée :",o:["Par tout le monde si la place est libre depuis plus d'une heure","Uniquement par un véhicule avec la carte européenne de stationnement handicapé","Par les véhicules de livraison le matin","Par les femmes enceintes"],r:[1],x:"Places handicapées : réservées aux véhicules affichant la carte européenne de stationnement (macaron handicapé). Amende majorée en cas d'infraction.",tip:"♿ Amende 135 € doublée pour stationnement illicite sur place PMR. Respectez ces places."},
{c:"Stationnement",e:"🚔",d:2,m:false,q:"Une fourrière peut immédiatement enlever votre véhicule en cas de :",o:["Tout stationnement dépassant 2 heures","Stationnement dangereux ou très gênant (voie de tram, accès pompiers)","Simple stationnement en zone bleue sans disque","Tout stationnement payant non réglé"],r:[1],x:"Enlèvement immédiat pour stationnement dangereux ou très gênant : voie de tram, accès pompiers, passage piéton, voie réservée.",tip:"🚛 Fourrière immédiate = infraction grave. Coût : 150-230 € (hors amende). Très dissuasif."},
{c:"Stationnement",e:"🌙",d:2,m:false,q:"La nuit, en agglomération, les feux de position suffisent-ils si vous êtes garé en dehors d'une zone éclairée ?",o:["Oui, les feux de position suffisent","Non : si la route est non éclairée, vous devez laisser les feux de stationnement ou de croisement","Peu importe, vous êtes garé","Oui si vous avez mis le frein à main"],r:[0],x:"En agglomération éclairée (c'est généralement le cas), les feux de position (veilleuses) suffisent. Sur route non éclairée, gardez un feu allumé côté circulation.",tip:"💡 Règle pratique : en ville éclairée = feux de position OK. Route sombre = feux de stationnement ou croisement."},
{c:"Stationnement",e:"🔴",d:3,m:true,q:"Le stationnement est interdit dans les situations suivantes :",o:["Sur trottoir (sauf autorisation locale)","À moins de 5 m d'une intersection","Devant les bouches d'incendie (5 m)","À moins de 15 m d'un arrêt de bus","Sur voie de tramway"],r:[0,1,2,3,4],x:"Toutes ces situations sont des infractions de stationnement. Le code de la route est très précis sur chacune d'elles.",tip:"📋 Mémo TIBAS : Trottoir, Intersections (<5m), Bouches d'incendie (<5m), Arrêts bus (<15m), voies de Signalisation spéciale."},

// ── SÉCURITÉ — suite (10) ────────────────────────────────────────
{c:"Sécurité",e:"🔒",d:2,m:false,q:"Un enfant de 10 kg doit être installé dans un siège :",o:["Groupe 0+ (coque) ou groupe 1","Groupe 0 uniquement (nacelle)","Siège rehausseur avec ceinture adulte","N'importe quel siège homologué"],r:[0],x:"Enfant 10 kg = siège groupe 0+ (jusqu'à 13 kg, dos à la route) ou groupe 1 (9-18 kg, face à la route). L'homologation i-Size ou ECE R44 est obligatoire.",tip:"👶 Le dos à la route est recommandé le plus longtemps possible. Beaucoup plus sécurisé en cas de choc frontal."},
{c:"Sécurité",e:"💺",d:2,m:false,q:"L'appui-tête est réglé correctement quand :",o:["Il touche le haut du crâne","Le milieu de l'appui-tête est à la hauteur des yeux ou des oreilles","Il est le plus haut possible","Il est à la hauteur des épaules"],r:[1],x:"L'appui-tête doit être à la hauteur des yeux ou des oreilles (milieu de l'appui-tête). Trop bas = risque de coup du lapin aggravé.",tip:"👁️ Milieu appui-tête = yeux/oreilles. Trop bas = pas de protection. Réglez-le avant de partir."},
{c:"Sécurité",e:"🔧",d:2,m:false,q:"La profondeur minimale légale des rainures d'un pneu est :",o:["0,5 mm","1,6 mm","3 mm","2 mm"],r:[1],x:"Profondeur minimale légale : 1,6 mm. En dessous, le pneu est hors normes et dangereux. En pratique, remplacement recommandé dès 3 mm.",tip:"🔧 Témoin d'usure : petit picot dans les rainures à 1,6 mm. Quand il rase = remplacement obligatoire."},
{c:"Sécurité",e:"🌡️",d:2,m:false,q:"Les pneus hiver (ou 4 saisons) sont obligatoires en France dans :",o:["Toute la France de novembre à mars","Dans les communes listées en zone de montagne, de novembre à mars","Uniquement sur les routes de montagne","Seulement si la neige est présente"],r:[1],x:"Depuis novembre 2021 (loi Montagne 2) : pneus hiver ou 4 saisons obligatoires dans les communes listées, du 1er novembre au 31 mars. Amende 135 €.",tip:"🏔️ Liste des communes concernées sur le site du gouvernement. Souvent les zones de montagne et préalpines."},
{c:"Sécurité",e:"🔥",d:2,m:false,q:"En cas d'incendie dans le moteur, vous devez :",o:["Ouvrir le capot pour ventiler","NE PAS ouvrir le capot : appelez les secours, éloignez-vous, utilisez un extincteur sans ouvrir","Verser de l'eau directement sur le moteur","Continuer à rouler pour ventiler"],r:[1],x:"Ouvrir le capot active l'incendie en apportant de l'oxygène. Appelez le 18, éloignez-vous, utilisez l'extincteur par les orifices si disponible.",tip:"🔥 Capot fermé = moins d'oxygène = incendie contenu. Ouvrir = embrasement immédiat."},
{c:"Sécurité",e:"⚡",d:2,m:false,q:"Traverser une flaque d'eau profonde à grande vitesse peut provoquer :",o:["Uniquement une projection d'eau","L'aquaplaning : perte totale d'adhérence","Un court-circuit électronique","Un embrayage mouillé"],r:[1],x:"Traverser une flaque profonde à vitesse excessive crée un film d'eau sous les pneus = aquaplaning = perte de contrôle totale.",tip:"💧 Approche d'une flaque profonde = réduire la vitesse AVANT. Trop tard une fois dessus."},
{c:"Sécurité",e:"👶",d:2,m:false,q:"Un enfant de 3 ans, 15 kg, peut-il voyager en siège rehausseur simple (sans dossier) ?",o:["Oui, à partir de 3 ans c'est autorisé","Non : un rehausseur sans dossier est autorisé uniquement dès 15 kg ET 100 cm minimum","Oui avec une ceinture adulte","Non, il faut attendre 6 ans"],r:[1],x:"Rehausseur sans dossier : autorisé dès 15 kg ET 100 cm. Un enfant léger ou trop petit doit rester dans un siège avec dossier.",tip:"📏 Double condition : poids ET taille. Les deux doivent être atteints."},
{c:"Sécurité",e:"🏍️",d:2,m:false,q:"Un motocycliste doit porter, en plus du casque :",o:["Uniquement des gants homologués","Des gants homologués CE, des protections corps","Aucun équipement supplémentaire n'est obligatoire","Une veste réfléchissante"],r:[0],x:"Depuis 2016, les gants homologués CE sont obligatoires pour les conducteurs de deux-roues motorisés. Les autres protections (dorsale, botte) sont recommandées mais non obligatoires.",tip:"🧤 Gants CE = seule obligation supplémentaire au casque. Les autres EPI sont fortement conseillés mais pas obligatoires."},
{c:"Sécurité",e:"😴",d:2,m:true,q:"Les signes précurseurs de somnolence au volant sont :",o:["Picotements des yeux","Difficulté à se souvenir des derniers kilomètres parcourus","Yeux qui se ferment involontairement","Impatience et irritabilité excessive","Tête qui tombe en avant"],r:[0,1,2,3,4],x:"Tous ces signes annoncent une somnolence dangereuse. À la moindre somnolence : arrêtez-vous, ne forcez pas. Une sieste de 20 min peut sauver des vies.",tip:"😴 Astuce anti-somnolence : café + sieste de 20 min = effet maximum. Le café seul est insuffisant."},
{c:"Sécurité",e:"🌊",d:3,m:false,q:"En cas d'inondation soudaine sur la route, vous devez :",o:["Forcer le passage rapidement pour éviter d'être bloqué","Ne pas vous engager : 30 cm d'eau peuvent emporter un véhicule","Réduire la vitesse à 30 km/h et traverser","Allumer les feux de détresse et traverser lentement"],r:[1],x:"30 cm d'eau peuvent emporter un véhicule. 50 cm = perte de contrôle totale. Ne jamais forcer un passage inondé.",tip:"⚠️ 'Faites demi-tour, ne vous noyez pas' : la règle américaine s'applique aussi en France."},

// ── CONDUITE — suite (10) ───────────────────────────────────────
{c:"Conduite",e:"⛽",d:2,m:false,q:"Descendre une côte au point mort (embrayage débrayé) :",o:["Économise le carburant","Est dangereux : perte de l'effet frein moteur et surchauffe des freins","Est conseillé pour les boîtes automatiques","Est identique à descendre en prise"],r:[1],x:"Descente au point mort : pas de frein moteur → freins seuls → surchauffe → perte d'efficacité (fading). Danger réel dans les longs cols.",tip:"⛽ Paradoxe : moderne = injection coupée en frein moteur = 0 carburant. Au point mort = consomme du carburant ET est dangereux."},
{c:"Conduite",e:"🚛",d:2,m:false,q:"Sur autoroute, les poids lourds > 3,5 t sont limités à :",o:["110 km/h","100 km/h","90 km/h","80 km/h"],r:[2],x:"Les poids lourds > 3,5 t sont limités à 90 km/h sur autoroute (80 km/h sur routes à 2 voies). Ils sont souvent limités à 110 km/h sur voies express.",tip:"🚛 PL > 3,5 t : 90 autoroute, 80 route, 50 agglomération. Rappel utile pour comprendre les dépassements."},
{c:"Conduite",e:"🔆",d:2,m:false,q:"Les feux antibrouillard AVANT peuvent être utilisés :",o:["Uniquement par temps de pluie","Uniquement si la visibilité est inférieure à 50 m","Par mauvais temps réduisant la visibilité (brouillard, forte pluie, neige)","À tout moment pour améliorer l'éclairage"],r:[2],x:"Feux antibrouillard avant : autorisés quand la visibilité est réduite (brouillard, forte pluie, neige). Pas par simple pluie légère.",tip:"🔆 Antibrouillard avant = mauvais temps réduisant la visibilité. Pas pour 'voir mieux' par temps clair."},
{c:"Conduite",e:"🚗",d:1,m:false,q:"Avant de démarrer, vous devez vous assurer que :",o:["Uniquement la ceinture du conducteur est attachée","Tous les passagers sont installés et ceinturés","Uniquement les enfants sont ceinturés","Le conducteur seul a la responsabilité de sa ceinture"],r:[1],x:"Le conducteur est responsable que tous les passagers soient ceinturés. Pour les passagers majeurs, une responsabilité partagée s'applique.",tip:"🔒 Le conducteur est pénalement responsable des passagers mineurs non ceinturés. Pour les majeurs, amende partagée."},
{c:"Conduite",e:"🌧️",d:2,m:false,q:"Par temps de neige ou de verglas, la distance de freinage peut être multipliée par :",o:["2 fois","4 à 10 fois","1,5 fois","3 fois"],r:[1],x:"Sur verglas, la distance de freinage peut être multipliée par 4 à 10 selon les conditions et la vitesse. La prudence extrême s'impose.",tip:"❄️ Sur verglas : la distance de freinage à 50 km/h peut dépasser 200 m. Réduisez drastiquement la vitesse."},
{c:"Conduite",e:"🔄",d:2,m:false,q:"Pour effectuer un créneau (stationnement parallèle), vous devez :",o:["Actionner les feux de détresse","Vérifier l'absence de cyclistes ou piétons avant d'effectuer la marche arrière","Uniquement regarder dans le rétroviseur central","Klaxonner avant de reculer"],r:[1],x:"Toute manœuvre de marche arrière nécessite de vérifier l'absence d'obstacles, de cyclistes et de piétons. Utilisez tous vos rétroviseurs.",tip:"👁️ Marche arrière = angle mort important. Tournez la tête. Rétroviseurs insuffisants."},
{c:"Conduite",e:"🚦",d:2,m:false,q:"Vous approchez d'un passage à niveau avec feux clignotants. Vous devez :",o:["Passer rapidement avant la barrière","Vous arrêter AVANT les rails et attendre que les feux s'éteignent","Passer si vous ne voyez pas de train","Vous arrêter sur les rails si nécessaire"],r:[1],x:"Feux clignotants au PN = arrêt OBLIGATOIRE avant les rails. N'avancez pas tant que les feux clignotent, même si aucun train n'est visible.",tip:"⚠️ Train à 160 km/h = bruit audible très tard. Arrêtez-vous toujours. Ne tentez jamais le passage."},
{c:"Conduite",e:"🏎️",d:2,m:false,q:"Pour dépasser en sécurité, vous devez disposer d'une distance de visibilité d'au moins :",o:["100 mètres","150 mètres","300 mètres","500 mètres"],r:[2],x:"Pour doubler un véhicule, il faut environ 300 m de visibilité minimale (selon la vitesse). À 90 km/h, compter 3-4 secondes de manœuvre.",tip:"📐 300 m = minimum à 80-90 km/h. À 110 km/h, pensez plutôt 400-500 m. Soyez généreux."},
{c:"Conduite",e:"⚠️",d:3,m:true,q:"Circuler en convoi : les règles spécifiques sont :",o:["Distance entre véhicules : max 50 m","Les véhicules de queue doivent signaler le convoi","Les dépassements du convoi sont interdits pour les autres","Vitesse réduite si le convoi dépasse 25 m de long","Les convois de nuit doivent être signalés"],r:[0,1,3,4],x:"Convoi : distance max 50 m entre véhicules, signalisation obligatoire, vitesse réduite si > 25 m. Le dépassement d'un convoi n'est pas interdit pour les autres.",tip:"🚗🚗🚗 Convois : fréquents lors de déménagements ou cortèges. Respectez les règles spécifiques."},
{c:"Conduite",e:"🌙",d:2,m:false,q:"La nuit, en approchant d'un virage, vous devez :",o:["Rester en feux de route jusqu'au dernier moment","Passer en feux de croisement avant le virage si un véhicule peut arriver en face","Klaxonner pour prévenir","Accélérer pour traverser le virage rapidement"],r:[1],x:"Avant un virage : si un véhicule peut arriver en face, passez en feux de croisement. Vous évitez d'éblouir et d'être ébloui.",tip:"🌙 Habitude recommandée : passer en code systématiquement avant les virages sur route sinueuse."},

// ── AUTOROUTE — suite (8) ───────────────────────────────────────
{c:"Autoroute",e:"⚡",d:2,m:false,q:"Un véhicule électrique en panne sur autoroute avec batterie à 0 peut :",o:["Appeler le 3617 (assistance autoroutes)","Utiliser une borne de recharge de la BAU","Être remorqué uniquement si la plate-forme est disponible","Bénéficier d'une intervention du télépéage"],r:[0],x:"En cas de panne sur autoroute, appelez via les bornes d'urgence (tous les 2 km) ou le 3617. L'opérateur autoroutier gère l'intervention.",tip:"📞 Bornes orange tous les 2 km sur autoroute = appel gratuit vers le PC autoroutier. Priorité sur le 112 pour ce type de panne."},
{c:"Autoroute",e:"🅿️",d:1,m:false,q:"Sur autoroute, la fréquence recommandée des pauses est :",o:["Toutes les 4 heures","Toutes les 2 heures ou 200 km","Uniquement quand vous vous sentez fatigué","Toutes les 3 heures"],r:[1],x:"Pause toutes les 2 heures ou 200 km : recommandation officielle. La fatigue s'accumule insidieusement, même sans somnolence ressentie.",tip:"⏱️ La fatigue multiplie les accidents par 3. Arrêtez-vous même si vous ne vous sentez pas fatigué."},
{c:"Autoroute",e:"🚛",d:2,m:false,q:"Sur autoroute à 3 voies, où les poids lourds > 3,5 t doivent-ils circuler ?",o:["Sur toutes les voies","Uniquement sur les deux voies de droite","Uniquement sur la voie la plus à droite","Sur n'importe quelle voie si < 90 km/h"],r:[1],x:"Les poids lourds > 3,5 t sont interdits sur la voie de gauche des autoroutes à 3 voies ou plus.",tip:"🚛 PL : 2 voies de droite max sur autoroute 3 voies. Voie gauche = dépassement voitures uniquement."},
{c:"Autoroute",e:"🌧️",d:2,m:false,q:"Sur autoroute, en cas d'aquaplaning, vous devez :",o:["Freiner brusquement pour réduire la vitesse","Relâcher l'accélérateur progressivement et ne pas braquer","Tourner le volant vers le bas-côté","Accélérer pour sortir du film d'eau"],r:[1],x:"Aquaplaning : relâchez doucement l'accélérateur, ne brusquez pas le volant, attendez le retour d'adhérence. Freiner = pire réaction.",tip:"💧 Aquaplaning à 130 km/h : quelques secondes de panique peuvent être fatales. Restez calme et droit."},
{c:"Autoroute",e:"💰",d:1,m:false,q:"Refuser de payer un péage d'autoroute est :",o:["Une infraction mineure","Une fraude punie d'une amende pouvant aller jusqu'à 375 €","Autorisé si vous manquez de monnaie","Toléré la première fois"],r:[1],x:"Fraude au péage : amende jusqu'à 375 €. Les systèmes de reconnaissance de plaques permettent désormais la verbalisation ultérieure.",tip:"💳 Conseils : T-pass ou télépéage pour les autoroutes. Plus de problème de monnaie."},
{c:"Autoroute",e:"🔦",d:2,m:false,q:"En cas de bouchon soudain sur autoroute ('accident coup de frein'), vous devez :",o:["Freiner brusquement et allumer les warnings","Allumer les warnings IMMÉDIATEMENT et freiner progressivement","Klaxonner pour alerter les suivants","Vous rabattre sur la BAU"],r:[1],x:"Bouchon soudain : warnings en PREMIER (réflexe immédiat), puis freinage progressif. Alertez les suivants visuellement avant de ralentir.",tip:"⚠️ Warnings d'abord = alertez les suivants. Puis freinez. L'ordre est fondamental."},
{c:"Autoroute",e:"🚶",d:3,m:false,q:"La 'voie d'entrecroisement' sur autoroute est la zone où :",o:["Deux voies de circulation normales se croisent","Une bretelle d'entrée et une bretelle de sortie se chevauchent","Les poids lourds doivent doubler","La vitesse est réduite à 110 km/h"],r:[1],x:"Voie d'entrecroisement : zone courte entre bretelle d'entrée et bretelle de sortie rapprochées. Prudence : les manœuvres se concentrent.",tip:"↔️ Entrecroisement = attention maximale. Ceux qui entrent et ceux qui sortent se croisent en peu d'espace."},
{c:"Autoroute",e:"🛣️",d:2,m:false,q:"Sur une autoroute à péage, une voiture tractant une caravane est limitée à :",o:["130 km/h","110 km/h","100 km/h","90 km/h"],r:[1],x:"Voiture + caravane ou remorque de PTAC > 500 kg : limitée à 110 km/h sur autoroute (sauf si limitation inférieure).",tip:"🚐 Ensemble + remorque lourde = 110 km/h max sur autoroute, 100 km/h voie express, 80 km/h route."},

// ── DOCUMENTS — suite (8) ───────────────────────────────────────
{c:"Documents",e:"📋",d:2,m:false,q:"L'attestation d'assurance (carte verte) doit être :",o:["Dans le portefeuille du propriétaire uniquement","Dans le véhicule, accessible lors d'un contrôle","Présentée uniquement en cas d'accident","Envoyée à la préfecture chaque année"],r:[1],x:"L'attestation d'assurance doit se trouver dans le véhicule assuré, pas chez le propriétaire. Elle doit être présentable lors de tout contrôle.",tip:"📋 Vérifiez que votre carte verte est dans le véhicule avant de partir. Sa validité aussi !"},
{c:"Documents",e:"🔑",d:2,m:false,q:"La suspension administrative du permis (par préfet) diffère de la suspension judiciaire (par juge) car :",o:["La suspension administrative est toujours plus longue","La suspension administrative est immédiate, sans procès, pour faits graves constatés","La suspension judiciaire ne peut pas dépasser 1 an","Elles ont exactement les mêmes effets"],r:[1],x:"Suspension administrative : immédiate sur décision du préfet (sécurité routière). Judiciaire : décidée par un tribunal. Peuvent se cumuler.",tip:"⚖️ Les deux types de suspension peuvent se cumuler. La préfectorale peut précéder le jugement."},
{c:"Documents",e:"📝",d:2,m:false,q:"En cas de perte du permis de conduire, vous devez :",o:["Faire une déclaration de perte à la mairie et demander un duplicata via l'ANTS","Vous rendre au commissariat uniquement","Ne plus conduire jusqu'à la restitution du permis","Attendre un an avant de redemander"],r:[0],x:"Perte de permis : déclarez la perte (commissariat ou en ligne) et demandez un duplicata sur ants.gouv.fr. Vous pouvez continuer à conduire (avec le récépissé).",tip:"🖥️ Toutes les démarches carte grise, permis = ants.gouv.fr. Plus de guichet préfecture pour ça."},
{c:"Documents",e:"🚗",d:2,m:false,q:"Lors d'une vente, l'acheteur peut circuler avec le véhicule avant d'avoir sa carte grise si :",o:["Il a une photocopie de l'ancienne carte grise","Il a le certificat de cession signé et l'ancienne carte grise barrée","Il a une assurance et l'accord verbal du vendeur","Uniquement si le vendeur est présent dans le véhicule"],r:[1],x:"L'acheteur peut circuler avec le certificat de cession + ancienne carte grise barrée, pendant 30 jours maximum après la vente.",tip:"📄 Certificat de cession + CI barrée = conduite légale 30 jours. Demandez la carte grise rapidement."},
{c:"Documents",e:"🎓",d:2,m:false,q:"La Conduite Accompagnée (AAC) peut débuter à :",o:["14 ans","15 ans","16 ans","17 ans"],r:[1],x:"L'AAC (Apprentissage Anticipé de la Conduite) peut commencer dès 15 ans avec un accompagnateur désigné. Le permis est délivrable à 17 ans et 1 mois.",tip:"🎓 AAC = moins d'accidents, réduction de la période probatoire (2 ans au lieu de 3). Fortement conseillé."},
{c:"Documents",e:"💳",d:3,m:false,q:"Le permis à points démarre avec combien de points pour un conducteur AAC ?",o:["6 points dès 17 ans","12 points immédiatement","6 points, avec 2 points supplémentaires par an de conduite sans infraction grave","Aucun point : il faut les gagner"],r:[2],x:"Permis AAC : démarre à 6 points, gagne 3 points/an sans infraction grave (2 ans de probatoire au lieu de 3). Capital plein (12 pts) atteint plus vite.",tip:"📈 AAC : capital plein en 2 ans et demi environ. Conduite normale (3 ans). Avantage clair pour les conduite accompagnée."},
{c:"Documents",e:"🛠️",d:2,m:false,q:"Après un contrôle technique avec des défaillances majeures, vous disposez de :",o:["30 jours pour faire les réparations et repasser la contre-visite","7 jours pour circuler jusqu'au garage","2 mois pour repasser la visite","Aucun délai : le véhicule est immobilisé sur place"],r:[0],x:"Défaillances majeures au CT : 2 mois maximum pour faire réparer et repasser la contre-visite. Le véhicule peut circuler pour aller chez le réparateur.",tip:"🔧 Défaillances critiques = immobilisation immédiate. Majeures = 2 mois de délai. Mineures = juste notification."},
{c:"Documents",e:"🌍",d:2,m:false,q:"Le permis de conduire européen (permis B) est-il valable dans tous les pays de l'UE ?",o:["Oui, dans toute l'UE sans formalité supplémentaire","Non, il faut une traduction officielle","Oui, mais uniquement pour 3 mois","Seulement dans les pays Schengen"],r:[0],x:"Le permis B européen est valable dans tous les États membres de l'UE sans démarche particulière. Pour les pays hors UE, vérifiez les accords bilatéraux.",tip:"🌍 Hors UE : vérifiez si un permis international est nécessaire. Disponible en préfecture ou en ligne."},

// ── ÉCLAIRAGES — suite (7) ──────────────────────────────────────
{c:"Éclairages",e:"☀️",d:2,m:false,q:"Les feux diurnes (DRL) automatiques permettent de se passer de :",o:["Feux de croisement en ville","Feux de position (veilleuses) en journée","Feux de route la nuit","Feux antibrouillard arrière"],r:[1],x:"Les feux diurnes (DRL) remplacent les feux de position (veilleuses) en journée. Ils sont moins consommateurs et obligatoires sur les véhicules récents.",tip:"☀️ DRL = allumage automatique en journée. Ils n'éclairent pas l'avant pour vous, mais vous rendent visible."},
{c:"Éclairages",e:"🔵",d:2,m:false,q:"Un véhicule avec un gyrophare bleu (sans sirène) est :",o:["Prioritaire et vous devez vous arrêter","Un véhicule à signalisation spéciale (dépanneuse, escorte) non prioritaire","Un véhicule de police toujours","Un véhicule d'urgence prioritaire"],r:[1],x:"Gyrophare bleu seul (sans sirène) = véhicule de signalisation (dépanneurs, escortes, médecins…) non prioritaire. Sirène + gyrophare = prioritaire.",tip:"🔵 Bleu seul = attention. Bleu + sirène = prioritaire. La sirène fait la différence."},
{c:"Éclairages",e:"🟡",d:2,m:false,q:"Un gyrophare orange sur un véhicule indique :",o:["Un véhicule de police judiciaire","Un véhicule d'intervention : travaux, convoi exceptionnel, véhicule lent","Un véhicule médical urgent","Un véhicule d'escorte diplomatique"],r:[1],x:"Gyrophare orange = signalisation de danger ou de véhicule lent : engins de travaux, convois exceptionnels, dépanneuses, véhicules de balayage.",tip:"🟡 Orange = attention, danger ou obstacle lent. Ralentissez et soyez prudent."},
{c:"Éclairages",e:"💡",d:1,m:false,q:"Les feux de position (veilleuses) sont visibles à :",o:["150 mètres","300 mètres","30 à 40 mètres","500 mètres"],r:[1],x:"Les feux de position sont visibles à environ 300 mètres par temps clair. Ils signalent la présence du véhicule mais n'éclairent pas la route.",tip:"👁️ Feux de position = être vu, pas voir. Leur rôle est la signalisation, pas l'éclairage."},
{c:"Éclairages",e:"⚠️",d:2,m:false,q:"Il est interdit d'utiliser les feux antibrouillard arrière :",o:["Par temps de pluie légère (visibilité > 50 m)","En tunnel","Sur autoroute uniquement","Avec des feux de route"],r:[0],x:"Les feux antibrouillard arrière sont interdits par pluie légère (visibilité > 50 m) : ils éblouissent les conducteurs derrière. Uniquement si visibilité < 50 m.",tip:"🌧️ Pluie légère = feux antibrouillard arrière INTERDITS. Ils éblouissent et sont sanctionnés."},
{c:"Éclairages",e:"🚗",d:2,m:false,q:"Sur une route éclairée en agglomération, les feux de croisement sont-ils obligatoires ?",o:["Non, les feux de position suffisent","Oui, les feux de croisement sont obligatoires même en ville éclairée","Uniquement après minuit","Seulement si d'autres voitures circulent"],r:[0],x:"En agglomération éclairée, les feux de position (veilleuses) suffisent. Les feux de croisement sont toutefois recommandés pour être plus visible.",tip:"💡 Légalement : veilleuses OK en ville éclairée. Mais les feux de croisement sont recommandés par la sécurité routière."},
{c:"Éclairages",e:"🌙",d:2,m:false,q:"Quand faut-il obligatoirement passer des feux de route aux feux de croisement ?",o:["Uniquement face à un véhicule venant en sens inverse","Face à tout véhicule : en sens inverse ET devant vous","Uniquement sur route bidirectionnelle","Seulement si l'autre conducteur vous fait un appel de phares"],r:[1],x:"Feux de croisement obligatoires dès qu'un véhicule approche en face OU que vous en suivez un. Évite d'éblouir dans les deux cas.",tip:"🌙 Devant + en face = tous les cas. Passez en code dès qu'un véhicule est visible."},

// ── ENVIRONNEMENT — suite (10) ──────────────────────────────────
{c:"Environnement",e:"♻️",d:2,m:false,q:"Le malus écologique s'applique à l'achat de véhicules :",o:["Anciens de plus de 10 ans","Neufs ou d'occasion récente émettant beaucoup de CO2","Uniquement diesel","Sans vignette Crit'Air"],r:[1],x:"Le malus écologique (basé sur les émissions de CO2) s'applique à l'immatriculation de véhicules neufs ou récents fortement émetteurs.",tip:"♻️ Plus d'émissions = malus élevé. Jusqu'à plusieurs dizaines de milliers d'euros pour les plus polluants."},
{c:"Environnement",e:"⚡",d:2,m:false,q:"La recharge rapide (50 kW+) d'un véhicule électrique sur autoroute prend généralement :",o:["10 à 30 minutes pour 80 % de batterie","2 à 3 heures minimum","5 minutes comme un plein d'essence","1 heure exactement"],r:[0],x:"Recharge rapide (50-350 kW) : 20-30 min pour 80 % avec une borne 50 kW. Avec une borne 150-350 kW (ultra-rapide) : 15-20 min.",tip:"⚡ 80 % plutôt que 100 % : la recharge ralentit beaucoup après 80 %. Pratique sur autoroute."},
{c:"Environnement",e:"🌿",d:2,m:false,q:"Une voiture hybride rechargeable (PHEV) en mode électrique pur émet :",o:["Autant qu'un véhicule thermique","Beaucoup moins de CO2 en mode EV, zéro à l'échappement local","Plus de CO2 que le thermique seul","Des émissions variables selon la vitesse"],r:[1],x:"En mode électrique pur, le PHEV ne produit pas d'émissions à l'échappement. L'empreinte globale dépend de la source d'électricité.",tip:"🔋 PHEV efficace = chargez souvent ! En mode thermique seul, il consomme plus qu'un hybride classique."},
{c:"Environnement",e:"🌱",d:2,m:false,q:"La principale source de CO2 d'une voiture thermique est :",o:["La fabrication du véhicule","La combustion du carburant à l'usage","L'entretien mécanique","Le recyclage en fin de vie"],r:[1],x:"Sur le cycle de vie, la combustion du carburant représente 70-80 % des émissions de CO2 d'un véhicule thermique.",tip:"🌍 Pour réduire : rouler moins, rouler plus doux, véhicule moins puissant. C'est l'usage qui pollue le plus."},
{c:"Environnement",e:"🚗",d:2,m:false,q:"L'entretien régulier du véhicule (filtres, bougies, pression pneus) permet de :",o:["Uniquement améliorer la sécurité","Réduire la consommation de 5 à 15 % et les émissions","Uniquement prolonger la durée de vie","N'a aucun effet sur la consommation"],r:[1],x:"Un véhicule bien entretenu consomme 5 à 15 % de moins. Filtres encrassés, bougies usées, pneus sous-gonflés = surconsommation.",tip:"🔧 Entretien = économies de carburant + moins de pollution + meilleure sécurité. Triple bénéfice."},
{c:"Environnement",e:"🏙️",d:3,m:false,q:"En 2025, les ZFE (Zones à Faibles Émissions) sont obligatoires pour les agglomérations de plus de :",o:["50 000 habitants","100 000 habitants","150 000 habitants","200 000 habitants"],r:[1],x:"Depuis la loi Climat et Résilience (2021), les agglomérations de plus de 150 000 habitants devaient mettre en place des ZFE avant 2025.",tip:"🏙️ + de 150 000 hab. = ZFE obligatoire. Vérifiez votre vignette si vous visitez une grande ville française."},
{c:"Environnement",e:"🌬️",d:2,m:false,q:"La vitesse qui minimise la consommation de carburant sur route est généralement :",o:["50 km/h","70-80 km/h","90 km/h","110 km/h"],r:[1],x:"La consommation optimale se situe généralement entre 70 et 80 km/h pour la plupart des véhicules thermiques. Au-delà, la résistance aérodynamique augmente fortement.",tip:"🌬️ Résistance aérodynamique ∝ v². À 130 km/h, 3× plus de résistance qu'à 70 km/h. L'autoroute coûte cher."},
{c:"Environnement",e:"🚌",d:2,m:false,q:"Prendre le covoiturage plutôt que sa voiture seule permet de réduire l'empreinte carbone d'environ :",o:["10 %","30-60 % selon le taux d'occupation","80 %","Aucun effet si les voitures utilisent le même carburant"],r:[1],x:"Covoiturage à 2 personnes = empreinte divisée par 2 par personne. À 4 personnes = divisée par 4. Économies importantes.",tip:"🚗🚗 Covoiturage = moins d'émissions par personne, moins de trafic, moins de parking. Gagnant pour tous."},
{c:"Environnement",e:"🌊",d:2,m:false,q:"Les pluies intenses liées aux changements climatiques ont un impact sur la conduite car elles augmentent :",o:["Uniquement la consommation de carburant","Le risque d'aquaplaning et d'inondations soudaines (crues éclair)","La durée de vie des pneus","L'efficacité des freins"],r:[1],x:"Pluies intenses = risque accru d'aquaplaning (eau sur la chaussée) et de crues éclair soudaines. Adaptez toujours votre vitesse aux conditions.",tip:"🌊 Face à une route inondée : demi-tour. 30 cm d'eau peuvent emporter un véhicule."},
{c:"Environnement",e:"🔋",d:2,m:false,q:"Le bilan carbone d'un véhicule électrique dépend surtout de :",o:["La marque du véhicule","Le mix énergétique utilisé pour produire l'électricité","La couleur de la carrosserie","La taille de la batterie uniquement"],r:[1],x:"En France, le mix électrique très décarboné (nucléaire + renouvelables) rend les VE très peu émetteurs sur leur cycle de vie.",tip:"🔋 France = électricité peu carbonée → VE très avantageux. En Allemagne (charbon) → avantage réduit."},
]

// Assign _id and export
RAW.forEach((q, i) => { q._id = i })
export const BANQUE = RAW
export const CATEGORIES = ['Signalisation','Priorités','Vitesse','Alcool','Stationnement','Sécurité','Conduite','Autoroute','Documents','Éclairages','Environnement']
